def longest_bitonic_length(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # Longest increasing subsequence ending at index i
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Longest decreasing subsequence starting at index i
    lds = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if nums[j] < nums[i]:
                lds[i] = max(lds[i], lds[j] + 1)

    # The length of the longest bitonic subsequence is the maximum of lis[i] + lds[i] - 1
    return max(lis[i] + lds[i] - 1 for i in range(n))
