from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    queue = deque()
    visited = [[False] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '0':
                queue.append((i, j, 0, False))  # (row, col, distance, has_break)
                visited[i][j] = True

    while queue:
        r, c, dist, has_break = queue.popleft()

        if grid[r][c] == '1':
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                if grid[nr][nc] == '0':
                    visited[nr][nc] = True
                    queue.append((nr, nc, dist + 1, has_break))
                else:
                    if not has_break:
                        visited[nr][nc] = True
                        queue.append((nr, nc, dist + 1, True))

    return -1
