def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for line in program:
        if not line:
            continue
        parts = line.split()
        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'ADD':
            if len(stack) < 2:
                return []
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)
        elif parts[0] == 'SUB':
            if len(stack) < 2:
                return []
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif parts[0] == 'MUL':
            if len(stack) < 2:
                return []
            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)
        elif parts[0] == 'DIV':
            if len(stack) < 2:
                return []
            a = stack.pop()
            if a == 0:
                return []
            b = stack.pop()
            stack.append(b // a)
        elif parts[0] == 'MOD':
            if len(stack) < 2:
                return []
            a = stack.pop()
            if a == 0:
                return []
            b = stack.pop()
            stack.append(b % a)
        elif parts[0] == 'NEG':
            if len(stack) < 1:
                return []
            stack.append(-stack.pop())
        elif parts[0] == 'DUP':
            if len(stack) < 1:
                return []
            stack.append(stack[-1])
        elif parts[0] == 'SWAP':
            if len(stack) < 2:
                return []
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif parts[0] == 'DROP':
            if len(stack) < 1:
                return []
            stack.pop()
        elif parts[0] == 'OVER':
            if len(stack) < 2:
                return []
            stack.append(stack[-2])
        elif parts[0] == 'ROT':
            if len(stack) < 3:
                return []
            stack.append(stack[-3])
    return stack
