        if line.startswith('PUSH'):
            value = int(line.split()[1])
            stack.append(value)
        elif line.startswith('ADD'):
            if len(stack) < 2:
                return []
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)
        elif line.startswith('SUB'):
            if len(stack) < 2:
                return []
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif line.startswith('MUL'):
