            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)
        elif line.startswith('DIV'):
            if len(stack) < 2:
                return []
            a = stack.pop()
            if a == 0:
                return []
            b = stack.pop()
            stack.append(b // a)
        elif line.startswith('MOD'):
            if len(stack) < 2:
                return []
            a = stack.pop()
            if a == 0:
                return []
            b = stack.pop()
            stack.append(b % a)
        elif line.startswith('NEG'):
            if not stack:
                return []
            stack.append(-stack.pop())
        elif line.startswith('DUP'):
            if not stack:
                return []
            stack.append(stack[-1])
        elif line.startswith('SWAP'):
            if len(stack) < 2:
                return []
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif line.startswith('DROP'):
            if not stack:
                return []
            stack.pop()
        elif line.startswith('OVER'):
            if len(stack) < 2:
                return []
            stack.append(stack[-2])
        elif line.startswith('ROT'):
            if len(stack) < 3:
