def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    while i < len(source):
        if source[i].isspace():
            i += 1
            continue
        if source[i] in '(){}[],;':
            tokens.append(('symbol', source[i]))
            i += 1
        elif source[i].isalpha():
            j = i
            while j < len(source) and source[j].isalnum():
                j += 1
            tokens.append(('identifier', source[i:j]))
            i = j
        elif source[i].isdigit():
            j = i
            while j < len(source) and source[j].isdigit():
                j += 1
            tokens.append(('number', source[i:j]))
            i = j
        else:
            tokens.append(('other', source[i]))
            i += 1
    return tokens
