def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows or not aligns:
        return ""

    max_widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    def format_row(row, align):
        return "| " + " | ".join(
            row[i].ljust(max_widths[i]) if align[i] == '<' else
            row[i].rjust(max_widths[i]) if align[i] == '>' else
            row[i].center(max_widths[i]) for i in range(len(row))
        ) + " |"

    return "\n".join(format_row(row, aligns) for row in rows)
