def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for line in program:
        if not line:
            continue
        parts = line.split()
        if parts[0] == 'PUSH':
            if len(parts) != 2 or not parts[1].isdigit():
                return None
            stack.append(int(parts[1]))
        elif parts[0] == 'POP':
            if not stack:
                return None
            stack.pop()
        elif parts[0] == 'ADD':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)
        elif parts[0] == 'SUB':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif parts[0] == 'MUL':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)
        elif parts[0] == 'DIV':
            if len(stack) < 2:
                return None
            a = stack.pop()
            if a == 0:
                return None
            b = stack.pop()
            stack.append(b // a)
        elif parts[0] == 'END':
            break
        else:
            return None
    return stack if stack else None
