def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    # Create a set of blocked positions for quick lookup
    blocked_set = set(blocked)

    # Initialize the count of valid queens
    count = 0

    # Try placing a queen in each row
    for row in range(n):
        # Try placing a queen in each column of the current row
        for col in range(n):
            # Check if the position is blocked
            if (row, col) in blocked_set:
                continue
            # Check if the current position is under attack by any previously placed queen
            under_attack = False
            for r, c in blocked_set:
                # Check diagonal
                if abs(row - r) == abs(col - c):
                    under_attack = True
                    break
                # Check row and column
                if row == r or col == c:
                    under_attack = True
                    break
            if not under_attack:
                count += 1
    return count

