def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_stable():
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] > 3:
                    return False
        return True

    while not is_stable():
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] > 3:
                    grid[i][j] -= 4
                    for dx, dy in directions:
                        ni, nj = i + dx, j + dy
                        if 0 <= ni < rows and 0 <= nj < cols:
                            grid[ni][nj] += 1
    return grid
