def convert_base(number: str, from_base: int, to_base: int) -> str:
    # Convert number from from_base to decimal
    decimal_number = int(number, from_base)
    # Convert decimal number to to_base
    if to_base == 1:
        return '0' * decimal_number
    digits = []
    while decimal_number > 0:
        digits.append(str(decimal_number % to_base))
        decimal_number //= to_base
    return ''.join(reversed(digits))
```

