def count_interval_overlaps(intervals: list[tuple[int, int]]) -> int:
    if not intervals:
        return 0
    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    count = 1
    end = sorted_intervals[0][1]
    for start, stop in sorted_intervals[1:]:
        if start <= end:
            count += 1
            end = stop
        else:
            end = stop
    return count
