def weighted_harmonic_mean(vals: list[float], weights: list[float]) -> float:
    if len(vals) != len(weights):
        raise ValueError("The lengths of vals and weights must be equal.")
    if any(val <= 0 for val in vals) or any(weight <= 0 for weight in weights):
        raise ValueError("All values and weights must be positive.")
    total_weight = sum(weights)
    sum_weighted_reciprocal = sum(weight / val for val, weight in zip(vals, weights))
    return total_weight / sum_weighted_reciprocal
