from collections import defaultdict, deque

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for u, v in pairs:
        graph[u].append(v)
        in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        u = queue.popleft()
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return result
```

