def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = {}
    access_order = []
    evictions = []
    hits = 0
    misses = 0

    for op in operations:
        if op[0] == 'R':
            page = op[1]
            if page in cache:
                hits += 1
                access_order.remove(page)
                access_order.append(page)
            else:
                misses += 1
                if len(cache) >= capacity:
                    evicted = access_order.pop(0)
                    del cache[evicted]
                cache[page] = True
                access_order.append(page)
        elif op[0] == 'W':
            page = op[1]
            if page in cache:
                hits += 1
                access_order.remove(page)
                access_order.append(page)
            else:
                misses += 1
                if len(cache) >= capacity:
                    evicted = access_order.pop(0)
                    del cache[evicted]
                cache[page] = True
                access_order.append(page)

    return (access_order, [hits, misses])
