def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    from collections import defaultdict

    # Check if target is zero
    if target == 0:
        return 0

    # Initialize a dictionary to keep track of the minimum coins needed for each amount
    dp = defaultdict(lambda: float('inf'))
    dp[0] = 0

    # Iterate through each coin and its limit
    for coin, limit in zip(coins, limits):
        # Create a temporary dictionary to store new states
        temp_dp = dp.copy()
        # Try using the current coin up to its limit
        for amount in range(1, target + 1):
            for count in range(1, limit + 1):
                if amount - count * coin >= 0:
                    temp_dp[amount] = min(temp_dp[amount], dp[amount - count * coin] + count)
        dp = temp_dp

    return dp[target] if dp[target] != float('inf') else -1

