def teller_waits(arrivals: list[int], service_times: list[int], tellers: int) -> list[int]:
    if not arrivals or not service_times or len(arrivals) != len(service_times):
        return []

    events = []
    for i, arrival in enumerate(arrivals):
        events.append((arrival, i, service_times[i]))

    events.sort()
    result = []
    available_tellers = [0] * tellers
    heapq.heapify(available_tellers)

    for time, idx, service_time in events:
        if available_tellers[0] <= time:
            heapq.heappop(available_tellers)
            heapq.heappush(available_tellers, time + service_time)
            result.append(time)
        else:
            result.append(available_tellers[0])

    return result

