def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    from collections import defaultdict

    # Build a graph of conflicts
    conflict_graph = defaultdict(set)
    for a, b in conflicts:
        conflict_graph[a].add(b)
        conflict_graph[b].add(a)

    # Check if a guest is in conflict with another
    def is_conflict(guest1, guest2):
        return guest2 in conflict_graph[guest1]

    # Try to seat guests in a way that no two conflicting guests are seated together
    def can_seat(guests, seating, conflict_graph):
        if not guests:
            return True
        guest = guests[0]
        for i in range(len(seating)):
            if not seating[i] and not any(is_conflict(guest, seated) for seated in seating[i]):
                seating[i].append(guest)
                if can_seat(guests[1:], seating, conflict_graph):
                    return True
                seating[i].pop()
        return False

    # Try to seat all guests
    seating = [[] for _ in range(len(guests))]
    if can_seat(guests, seating, conflict_graph):
        return seating
    else:
        return []
