def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    order_counts = {}
    order_items = []

    for event in events:
        action, order_id, item_count = event
        if action == 'place':
            order_counts[order_id] = item_count
            order_items.append((order_id, item_count))
        elif action == 'update':
            if order_id in order_counts:
                order_counts[order_id] += item_count
                order_items[-1] = (order_id, order_counts[order_id])
        elif action == 'cancel':
            if order_id in order_counts:
                del order_counts[order_id]
                order_items = [item for item in order_items if item[0] != order_id]

    return order_counts, order_items
