import heapq

def top_k_elements(nums: list[int], k: int) -> list[int]:
    freq = defaultdict(int)
    first_occurrence = {}
    for i, num in enumerate(nums):
        if num not in first_occurrence:
            first_occurrence[num] = i
        freq[num] += 1

    # Use a heap to get the top k elements based on frequency and first occurrence
    heap = []
    for num, count in freq.items():
        heapq.heappush(heap, (-count, first_occurrence[num], num))

    result = []
    for _ in range(k):
        if heap:
            count_neg, first_idx, num = heapq.heappop(heap)
            result.append(num)

    return result
