import subprocess
import os

def compress_file(path: str) -> str:
    if not os.path.isfile(path):
        raise FileNotFoundError(f"The file {path} does not exist.")

    compressed_path = path + ".gz"

    try:
        subprocess.run(["gzip", path], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to compress file: {e}") from e

    if not os.path.isfile(compressed_path):
        raise RuntimeError(f"Compressed file {compressed_path} was not created.")

    return compressed_path
