import zlib

def inflate_payload(data: bytes) -> bytes:
    """
    Decompresses the given zlib-compressed data and returns the decompressed payload as bytes.
    If the data is empty, returns an empty byte string.
    """
    if not data:
        return b""
    try:
        return zlib.decompress(data)
    except zlib.error:
        return b""
