def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0
    def count_set_bits(n):
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count
    total = 0
    for num in range(lo, hi + 1):
        total += count_set_bits(num)
    return total
