def sparse_vector_dot(v1: dict[int, float], v2: dict[int, float]) -> float:
    dot_product = 0.0
    # Iterate through all keys in both dictionaries
    for index in set(v1.keys()).union(set(v2.keys())):
        val1 = v1.get(index, 0.0)
        val2 = v2.get(index, 0.0)
        dot_product += val1 * val2
    return round(dot_product, 3)
