import subprocess
import platform

def is_host_reachable(host: str) -> bool:
    if not host:
        return False

    # Determine the appropriate ping command based on the operating system
    if platform.system().lower() == "windows":
        ping_cmd = ["ping", "-n", "1", host]
    else:
        ping_cmd = ["ping", "-c", "1", host]

    try:
        result = subprocess.run(ping_cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=True)
        return result.returncode == 0
    except subprocess.CalledProcessError:
        return False
    except Exception as e:
        # Handle unexpected errors securely
        return False
