def caesar_cipher(text: str, shift: int) -> str:
    result = ""
    for char in text:
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                shifted = chr((ord(char) - ord('a') + shift_amount) % 26 + ord('a'))
            else:
                shifted = chr((ord(char) - ord('A') + shift_amount) % 26 + ord('A'))
            result += shifted
        else:
            result += char
    return result
