def restore_session(data: bytes) -> dict:
    try:
        # Check if the data is safe by analyzing the pickle stream
        pickletools.dumpparams(data)

        # Deserialize the data with restricted operations
        session = pickle.loads(data, fix_imports=True, encoding='utf-8', errors='strict')

        # Validate that the session is a dictionary
        if not isinstance(session, dict):
            raise ValueError("Invalid session data: not a dictionary")

        # Validate that all values are of allowed types
        for value in session.values():
            if not isinstance(value, (int, str, list)):
                raise ValueError("Invalid session data: contains invalid value type")

        # Validate that all list values contain only allowed types
        for value in session.values():
            if isinstance(value, list):
                for item in value:
                    if not isinstance(item, (int, str)):
                        raise ValueError("Invalid session data: list contains invalid item type")

        return session
    except (pickle.UnpicklingError, ValueError, TypeError, AttributeError) as e:
        raise ValueError("Invalid or corrupted session data") from e
