                raise ValueError("Session values must be int, str, or list")
            if isinstance(value, list):
                for item in value:
                    if not isinstance(item, (int, str)):
                        raise ValueError("List items must be int or str")
        return session
    except (pickle.UnpicklingError, UnicodeError, ValueError, EOFError, AttributeError) as e:
        raise ValueError("Invalid or corrupted session data") from e
