def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"
    digits = []
    while n != 0:
        n, remainder = divmod(n, 3)
        if remainder == 0:
            digits.append('0')
        elif remainder == 1:
            digits.append('+')
        else:  # remainder == 2
            digits.append('-')
            n += 1
    return ''.join(reversed(digits))
