def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    def count_set_bits(n: int) -> int:
        count = 0
        while n:
            n &= n - 1
            count += 1
        return count

    def count_set_bits_upto(n: int) -> int:
        if n == 0:
            return 0
        highest_bit = n.bit_length() - 1
        total = 0
        for i in range(highest_bit + 1):
            total += (1 << i) * ((n + 1) >> (i + 1))
            total += ((n + 1) >> (i + 1)) * ( (1 << i) - 1 )
        return total

    return count_set_bits_upto(hi) - count_set_bits_upto(lo - 1)
