def min_max_normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []
    min_val = min(nums)
    max_val = max(nums)
    if min_val == max_val:
        return [0.0 for _ in nums]
    return [round((x - min_val) / (max_val - min_val), 2) for x in nums]
