import os

def read_user_file(base_dir: str, filename: str) -> bytes | None:
    absolute_path = os.path.join(base_dir, filename)
    if not os.path.exists(absolute_path):
        return None
    if not os.path.isfile(absolute_path):
        return None
    # Check if the file is within the base directory to prevent directory traversal
    if not absolute_path.startswith(os.path.abspath(base_dir)):
        return None
    with open(absolute_path, 'rb') as f:
        return f.read()
