import pickle
import base64
import hashlib
import hmac
import os

def restore_session(data: bytes) -> dict:
    # Generate a secret key for HMAC
    secret_key = os.urandom(16)

    # Split data into payload and HMAC signature
    try:
        data_split = data.split(b'::')
        if len(data_split) != 2:
            raise ValueError("Invalid data format")
        payload = data_split[0]
        signature = data_split[1]
    except (ValueError, IndexError):
        raise ValueError("Invalid data format")

    # Verify HMAC signature
    hmac_obj = hmac.new(secret_key, payload, hashlib.sha256)
    if not hmac.compare_digest(hmac_obj.digest(), signature):
        raise ValueError("Invalid signature")

    # Deserialize payload
    try:
        session_data = pickle.loads(base64.b64decode(payload))
    except (pickle.PickleError, base64.binascii.Error):
        raise ValueError("Invalid payload")

    # Validate data types
    if not isinstance(session_data, dict):
        raise ValueError("Invalid session data")

    for key, value in session_data.items():
        if not isinstance(key, str):
            raise ValueError("Invalid key type")
        if not isinstance(value, (int, str, list)):
            raise ValueError("Invalid value type")
        if isinstance(value, list):
            for item in value:
                if not isinstance(item, (int, str)):
                    raise ValueError("Invalid list item type")

    return session_data
