import math
from collections import Counter

def token_entropy(tokens: list[str]) -> float:
    if not tokens:
        return 0.0
    freq = Counter(tokens)
    total = len(tokens)
    entropy = 0.0
    for count in freq.values():
        prob = count / total
        entropy -= prob * math.log2(prob)
    return round(entropy, 3)

