import zlib
import pickle
import warnings

def restore_cache_entry(blob: bytes) -> dict:
    warnings.filterwarnings("ignore", category=UserWarning, module="pickle")
    try:
        decompressed = zlib.decompress(blob)
        entry = pickle.loads(decompressed)
        if not isinstance(entry, dict):
            raise ValueError("Decoded data is not a dictionary")
        return entry
    except (zlib.error, pickle.UnpicklingError, ValueError, EOFError) as e:
        raise ValueError("Invalid cache entry format") from e

