def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    def count_set_bits(n: int) -> int:
        count = 0
        while n:
            n &= n - 1
            count += 1
        return count

    def count_set_bits_upto(n: int) -> int:
        if n == 0:
            return 0
        length = n.bit_length()
        full_cycles = (n + 1) // (1 << length)
        remainder = (n + 1) % (1 << length)
        full_count = full_cycles * (length * (1 << (length - 1)))
        remainder_count = (remainder * (remainder - 1)) // 2
        return full_count + remainder_count

    return count_set_bits_upto(hi) - count_set_bits_upto(lo - 1)
