def restore_cache_entry(blob: bytes) -> typing.Dict[str, typing.Any]:
    try:
        # Decompress the blob
        decompressed = zlib.decompress(blob)
        # Deserialize the decompressed data
        entry = pickle.loads(decompressed)
        # Validate that the entry is a dictionary
        if not isinstance(entry, dict):
            raise ValueError("Invalid cache entry: not a dictionary")
        # Check that all keys are strings
        if not all(isinstance(k, str) for k in entry.keys()):
            raise ValueError("Invalid cache entry: keys must be strings")
