        def is_allowed_value(value):
            return isinstance(value, (str, int, float, list, dict))

        if not all(is_allowed_value(v) for v in entry.values()):
            raise ValueError("Invalid cache entry: values must be of allowed types")
        return entry
    except (zlib.error, pickle.UnpicklingError, ValueError, TypeError) as e:
