import zlib
import pickle
import io

def restore_cache_entry(blob: bytes) -> dict:
    try:
        # Decompress the blob
        decompressed_data = zlib.decompress(blob)
        # Create a BytesIO object to read from
        byte_io = io.BytesIO(decompressed_data)
        # Load the pickle data
        entry = pickle.load(byte_io)
        # Check if the entry is a dictionary
        if not isinstance(entry, dict):
            raise ValueError("Invalid cache entry: not a dictionary")
        # Validate keys and values
        for key, value in entry.items():
            if not isinstance(key, str):
                raise ValueError("Invalid cache entry: key is not a string")
            if not isinstance(value, (str, int, float, list, dict)):
                raise ValueError("Invalid cache entry: value is of invalid type")
        return entry
    except (zlib.error, pickle.UnpicklingError, EOFError, ValueError) as e:
        raise ValueError("Failed to restore cache entry: " + str(e)) from e

