def smallest_lcs(a: str, b: str) -> str:
    m, n = len(a), len(b)
    dp = [[[-1 for _ in range(n + 1)] for _ in range(m + 1)] for _ in range(2)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[0][i][j] = 0
            elif a[i-1] == b[j-1]:
                dp[1][i][j] = dp[0][i-1][j-1] + 1
                dp[0][i][j] = dp[1][i][j]
            else:
                dp[1][i][j] = max(dp[0][i-1][j], dp[0][i][j-1])
                dp[0][i][j] = dp[1][i][j]

    lcs_len = dp[0][m][n]
    lcs = [''] * lcs_len
    i, j = m, n
    while i > 0 and j > 0:
        if a[i-1] == b[j-1]:
            lcs[lcs_len - 1] = a[i-1]
            i -= 1
            j -= 1
            lcs_len -= 1
        elif dp[0][i-1][j] > dp[0][i][j-1]:
            i -= 1
        else:
            j -= 1

    return ''.join(lcs)
