import zipfile
import os

def unzip_member_text(zip_path: str, member: str) -> str:
    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"The zip file {zip_path} does not exist.")

    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        if member not in zip_ref.namelist():
            raise KeyError(f"The member {member} is not present in the zip file.")

        # Ensure the member path is safe to prevent directory traversal attacks
        if not member.startswith(os.path.dirname(zip_path) + os.sep):
            raise ValueError("Invalid member path: potential directory traversal attempt.")

        with zip_ref.open(member) as file:
            content = file.read()
            return content.decode('utf-8')
