def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    if target == 0:
        return 0

    from collections import deque

    # Initialize a queue for BFS
    queue = deque([(0, 0)])  # (current_amount, coins_used)
    visited = set()
    visited.add(0)

    while queue:
        amount, count = queue.popleft()

        for i in range(len(coins)):
            coin = coins[i]
            limit = limits[i]
            # Try using 1 to limit coins of this type
            for num_coins in range(1, limit + 1):
                new_amount = amount + num_coins * coin
                if new_amount == target:
                    return count + num_coins
                elif new_amount < target and new_amount not in visited:
                    visited.add(new_amount)
                    queue.append((new_amount, count + num_coins))
    return -1

