import re

def is_valid_email(s: str) -> bool:
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')

    # Validate local part
    if not re.fullmatch(r'[a-zA-Z0-9._-]+', local):
        return False
    if not local or not local[0].isalnum() or not local[-1].isalnum():
        return False
    if '..' in local or '--' in local or '__' in local:
        return False

    # Validate domain part
    if '.' not in domain:
        return False
    parts = domain.split('.')
    if len(parts) < 2:
        return False
    for part in parts:
        if not part or not part.isalnum():
            return False
    if len(parts[-1]) < 2:
        return False

    return True
