def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    board = [[False for _ in range(n)] for _ in range(n)]
    blocked_set = set((r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n)

    def is_safe(row, col, queens):
        for r, c in queens:
            if c == col or r == row or abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(queens, col):
        if len(queens) == n:
            return 1
        count = 0
        for row in range(n):
            if (row, col) not in blocked_set and is_safe(row, col, queens):
                queens.append((row, col))
                count += backtrack(queens, col + 1)
                queens.pop()
        return count

    return backtrack([], 0)
