def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    from itertools import permutations

    if n == 0:
        return 1

    blocked_set = set(blocked)
    valid_positions = [(row, col) for row in range(n) for col in range(n) if (row, col) not in blocked_set]

    count = 0
    for perm in permutations(valid_positions):
        valid = True
        for i in range(n):
            for j in range(i + 1, n):
                row1, col1 = perm[i]
                row2, col2 = perm[j]
                if row1 == row2 or col1 == col2 or abs(row1 - row2) == abs(col1 - col2):
                    valid = False
                    break
            if not valid:
                break
        if valid:
            count += 1
    return count
