def identifier_to_snake(name: str) -> str:
    if not name:
        return ""

    result = []
    prev_char = ''
    for i, char in enumerate(name):
        if char in '_-':
            continue
        if i > 0:
            if (prev_char.isalpha() and char.isalpha() and prev_char.isupper() and char.islower()) or \
               (prev_char.isdigit() and char.isalpha()) or \
               (prev_char.isalpha() and char.isdigit()) or \
               (prev_char.isupper() and char.isupper() and i < len(name) - 1 and name[i+1].islower()):
                result.append('_')
        result.append(char.lower())
        prev_char = char
    return ''.join(result)
