from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False] * cols for _ in range(rows)]
    queue = deque([(start[0], start[1], 0, False)])  # (row, col, steps, broke_wall)

    while queue:
        r, c, steps, broke = queue.popleft()
        if (r, c) == end:
            return steps
        if broke:
            continue
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '#' and not broke:
                    queue.append((nr, nc, steps + 1, True))
                elif grid[nr][nc] != '#' and not visited[nr][nc]:
                    visited[nr][nc] = True
                    queue.append((nr, nc, steps + 1, broke))

    return -1
