def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)
    # Identity matrix
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]

    # Function to multiply two matrices under mod
    def multiply(a, b):
        return [
            [
                sum(a[i][k] * b[k][j] for k in range(n)) % mod
                for j in range(n)
            ]
            for i in range(n)
        ]

    # Function to perform matrix exponentiation using binary exponentiation
    def matrix_pow(mat, power):
        res = result
        while power > 0:
            if power % 2 == 1:
                res = multiply(res, mat)
            mat = multiply(mat, mat)
            power //= 2
        return res

    return matrix_pow(matrix, exp)
