import os

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # Handle root path
    if request_path == "/":
        file_path = os.path.join(web_root, "index.html")
    else:
        # Decode URL and construct file path
        decoded_path = os.path.normpath(os.path.join(web_root, request_path[1:]))
        # Ensure the file is within the web_root directory
        if not decoded_path.startswith(web_root):
            return 404, b"Not Found"
        file_path = decoded_path

    if os.path.isfile(file_path):
        with open(file_path, "rb") as f:
            content = f.read()
        return 200, content
    else:
        return 404, b"Not Found"
