def decode_runs(encoded: str) -> str:
    result = []
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            if i + 1 < len(encoded) and encoded[i + 1] == '~':
                # Handle the run token
                i += 2
                count = 0
                while i < len(encoded) and encoded[i].isdigit():
                    count = count * 10 + int(encoded[i])
                    i += 1
                if count > 0:
                    result.append(encoded[i - 1] * count)
            else:
                # Handle the literal token
                result.append(encoded[i + 1])
                i += 2
        else:
            result.append(encoded[i])
            i += 1
    return ''.join(result)
