def decode_runs(encoded: str) -> str:
    result = []
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            if i + 1 < len(encoded):
                if encoded[i + 1] == '~':
                    # Handle run token
                    i += 2
                    count = 0
                    while i < len(encoded) and encoded[i].isdigit():
                        count = count * 10 + int(encoded[i])
                        i += 1
                    if count == 0:
                        pass  # Skip the character
                    else:
                        result.append(encoded[i - 1] * count)
                else:
                    # Single character token
                    result.append(encoded[i + 1])
                    i += 2
            else:
                # Single backslash, treat as literal
                result.append('\\')
                i += 1
        else:
            # Regular character
            result.append(encoded[i])
            i += 1
    return ''.join(result)
