from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[[False for _ in range(cols)] for _ in range(rows)] for _ in range(2)]
    queue = deque()
    queue.append((start[0], start[1], 0, 0))  # (row, col, moves, walls_used)
    visited[0][start[0]][start[1]] = True

    while queue:
        r, c, moves, walls = queue.popleft()
        if (r, c) == end:
            return moves

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '#':
                    if walls < 1:
                        if not visited[1][nr][nc]:
                            visited[1][nr][nc] = True
                            queue.append((nr, nc, moves + 1, walls + 1))
                else:
                    if not visited[0][nr][nc]:
                        visited[0][nr][nc] = True
                        queue.append((nr, nc, moves + 1, walls))

    return -1
```

