import re

def identifier_to_snake(name: str) -> str:
    if not name:
        return ""

    # Split the name into parts based on separators (_ and -)
    parts = re.split(r'[_-]+', name)
    filtered_parts = [part for part in parts if part]

    # Process each part to handle camelCase and other cases
    result = []
    for part in filtered_parts:
        # Split on uppercase letters and digits
        split_parts = re.split(r'(?<=[a-z0-9])(?=[A-Z])', part)
        for sub_part in split_parts:
            # Split on lowercase and uppercase transitions
            sub_split = re.split(r'(?<=[a-z])(?=[A-Z])', sub_part)
            for sub_sub_part in sub_split:
                # Split on digit and letter transitions
                sub_sub_split = re.split(r'(?<=[0-9])(?=[a-z])', sub_sub_part)
                for sub_sub_sub_part in sub_sub_split:
                    result.append(sub_sub_sub_part.lower())

    return '_'.join(result)
