from collections import deque

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    queue = deque([(source, [source])])
    visited[source] = True
    count = 0

    while queue:
        node, path = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                new_path = path + [neighbor]
                if neighbor == target:
                    count += 1
                queue.append((neighbor, new_path))

    return count

