from collections import deque, defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    dist = [-1] * n
    dist[source] = 0
    prev = [0] * n

    q = deque([source])
    while q:
        u = q.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                prev[v] = prev[u] + 1
                q.append(v)
            elif dist[v] == dist[u] + 1:
                prev[v] += prev[u]

    return prev[target]

