    from itertools import permutations

    def is_valid(queen_positions):
        rows = set()
        cols = set()
        diag1 = set()
        diag2 = set()
        for r, c in queen_positions:
            if r in rows or c in cols or (r - c) in diag1 or (r + c) in diag2:
                return False
            rows.add(r)
            cols.add(c)
            diag1.add(r - c)
            diag2.add(r + c)
        return True

    valid_positions = []
    for r in range(n):
        for c in range(n):
