from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    queue = deque([(start[0], start[1], 0, False)])  # (row, col, moves, has_broken)

    while queue:
        r, c, moves, broken = queue.popleft()
        if (r, c) == end:
            return moves
        if (r, c, broken) in visited:
            continue
        visited.add((r, c, broken))

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '#':
                    if not broken:
                        queue.append((nr, nc, moves + 1, True))
                else:
                    queue.append((nr, nc, moves + 1, broken))

    return -1
