import os
from http import HTTPStatus

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # Handle root path
    if request_path == "/":
        request_path = "index.html"

    # Convert request path to a file path relative to web_root
    file_path = os.path.join(web_root, request_path.lstrip("/"))

    # Check if the file exists and is a regular file
    if os.path.isfile(file_path):
        with open(file_path, "rb") as f:
            content = f.read()
        return (HTTPStatus.OK.value, content)

    # If file not found, return 404
    return (HTTPStatus.NOT_FOUND.value, b"Not Found")

