import hashlib
import secrets

def hash_pin(pin: str) -> str:
    if not (pin.isdigit() and 4 <= len(pin) <= 6):
        raise ValueError("PIN must be a 4-6 digit string")
    salt = secrets.token_hex(16)
    hashed = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt.encode(), 100000)
    return salt + ':' + hashed.hex()

def check_pin(pin: str, stored: str) -> bool:
    if not (pin.isdigit() and 4 <= len(pin) <= 6):
        return False
    try:
        salt, hashed = stored.split(':', 1)
        hashed = bytes.fromhex(hashed)
    except (ValueError, IndexError):
        return False
    computed = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt.encode(), 100000)
    return computed.hex() == hashed.hex()
