def identifier_to_snake(name: str) -> str:
    import re
    if not name:
        return ""
    parts = re.split(r'[_-]+', name)
    result = []
    for part in parts:
        if not part:
            continue
        if not part[0].isalpha():
            continue
        converted = []
        for i, c in enumerate(part):
            if c.isupper() and i > 0:
                converted.append('_')
            converted.append(c.lower())
        result.append(''.join(converted))
    return '_'.join(result)
