def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    for size in sizes:
        if size > capacity:
            raise ValueError("All sizes must be less than or equal to capacity.")

    bins = []
    for size in sorted(sizes, reverse=True):
        placed = False
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                placed = True
                break
        if not placed:
            bins.append([size])
    return bins
