def decode_runs(encoded: str) -> str:
    result = []
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            i += 1
            if i < len(encoded):
                if encoded[i] == '~':
                    i += 1
                    if i < len(encoded) and encoded[i].isdigit():
                        count = 0
                        while i < len(encoded) and encoded[i].isdigit():
                            count = count * 10 + int(encoded[i])
                            i += 1
                        if i < len(encoded):
                            char = encoded[i]
                            result.append(char * count)
                            i += 1
                else:
                    result.append(encoded[i])
                    i += 1
        else:
            result.append(encoded[i])
            i += 1
    return ''.join(result)
