            if i + 1 < len(encoded):
                if encoded[i + 1] == '~':
                    # Handle token with ~ and number
                    i += 2
                    repeat = 0
                    while i < len(encoded) and encoded[i].isdigit():
                        repeat = repeat * 10 + int(encoded[i])
