def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    for size in sizes:
        if size > capacity:
            raise ValueError("All item sizes must be less than or equal to the capacity.")

    # Sort sizes in descending order
    sorted_sizes = sorted(sizes, reverse=True)

    # Initialize list of bins
    bins = []

    for size in sorted_sizes:
        placed = False
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                placed = True
                break
        if not placed:
            bins.append([size])

    return bins
