import re
import math

def evaluate_expression(expression: str) -> float:
    # Remove all whitespace from the expression
    expression = expression.replace(" ", "")

    # Check if the expression is empty
    if not expression:
        raise ValueError("Empty expression")

    # Check for invalid characters (excluding digits, operators, parentheses, and decimal point)
    if re.search(r'[^0-9+\-*/\.\(\)]', expression):
        raise ValueError("Invalid character in expression")

    # Check for balanced parentheses
    if expression.count('(') != expression.count(')'):
        raise ValueError("Unbalanced parentheses")

    # Check for invalid expressions like multiple operators in a row or invalid unary minus
    if re.search(r'([+\-*/\^])\1', expression) or re.search(r'([+\-*/\^])$', expression) or re.search(r'^([+\-*/\^])', expression):
        raise ValueError("Invalid expression")

    # Replace ** with ** for Python's exponentiation
    expression = expression.replace('**', '**')

    # Use Python's eval with a restricted environment to prevent security issues
    try:
        # Use math functions for unary minus and other operations
        result = eval(expression, {"__builtins__": None}, {"math": math, "**": math.pow, "+": lambda a, b: a + b, "-": lambda a, b: a - b, "*": lambda a, b: a * b, "/": lambda a, b: a / b})
        return float(result)
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except Exception as e:
        raise ValueError("Invalid expression") from e
