from collections import deque, defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    edge_set = set()

    for u, v in edges:
        if (u, v) not in edge_set and (v, u) not in edge_set:
            edge_set.add((u, v))
            graph[u].append(v)
            graph[v].append(u)

    dist = [-1] * n
    dist[source] = 0
    queue = deque([source])

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)

    if dist[target] == -1:
        return 0

    count = 0
    visited = [False] * n
    queue = deque([(source, [source])])
    visited[source] = True

    while queue:
        node, path = queue.popleft()
        if node == target:
            count += 1
            continue
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                new_path = path + [neighbor]
                queue.append((neighbor, new_path))

    return count
