import os
import stat

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # Normalize the request path and ensure it's relative to web_root
    normalized_path = os.path.normpath(request_path)
    if normalized_path.startswith('/') and normalized_path != '/':
        # Remove leading '/' and join with web_root
        relative_path = normalized_path[1:]
        file_path = os.path.join(web_root, relative_path)
    else:
        # Handle root path '/'
        file_path = os.path.join(web_root, 'index.html')

    # Check if the file exists and is a regular file
    if os.path.isfile(file_path):
        # Ensure the file is readable and not a directory
        if os.access(file_path, os.R_OK):
            with open(file_path, 'rb') as f:
                content = f.read()
            return (200, content)

    # Check if the file is a directory (for potential index.html)
    if os.path.isdir(file_path):
        index_path = os.path.join(file_path, 'index.html')
        if os.path.isfile(index_path) and os.access(index_path, os.R_OK):
            with open(index_path, 'rb') as f:
                content = f.read()
            return (200, content)

    # Security check: prevent directory traversal and access outside web_root
    if not os.path.commonprefix([file_path, web_root]) == web_root:
        return (403, b"Forbidden")

    return (404, b"Not Found")
