import hashlib
import re

def hash_pin(pin: str) -> str:
    if not re.fullmatch(r'\d{4,6}', pin):
        raise ValueError("PIN must be a 4 to 6 digit string.")
    return hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), b'salt', 100000).hex()

def check_pin(pin: str, stored: str) -> bool:
    try:
        if not re.fullmatch(r'\d{4,6}', pin):
            return False
        return hash_pin(pin) == stored
    except ValueError:
        return False
