import yaml
from typing import List, Dict

def parse_jobs(text: str) -> List[Dict[str, bool]]:
    if not text:
        return []
    try:
        # Load YAML content securely
        jobs = yaml.safe_load(text)
        if not isinstance(jobs, list):
            return []
        result = []
        for job in jobs:
            if not isinstance(job, dict):
                continue
            name = job.get('name')
            interval = job.get('interval')
            enabled = job.get('enabled', True)
            if name is not None and isinstance(interval, int):
                result.append({
                    'name': name,
                    'interval': interval,
                    'enabled': enabled
                })
        return result
    except yaml.YAMLError:
        return []
