from math import gcd
from functools import reduce

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            g, x, y = extended_gcd(b, a % b)
            return (g, y, x - (a // b) * y)

    def lcm(a, b):
        return a * b // gcd(a, b)

    x, m = congruences[0]
    for r, mod in congruences[1:]:
        g, p, q = extended_gcd(m, mod)
        if (r - x) % g != 0:
            return None
        lcm_val = lcm(m, mod)
        tmp = (r - x) // g * p
        x = x + tmp * m
        m = lcm_val
        x %= m

    return (x, m)
