def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)
    # Función para multiplicar dos matrices módulo mod
    def multiply(a, b):
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if a[i][k]:
                    for j in range(n):
                        result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    # Función para elevar una matriz al cuadrado módulo mod
    def square(mat):
        return multiply(mat, mat)

    # Función para elevar una matriz a la potencia exp usando exponenciación binaria
    def power(mat, power):
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]  # Matriz identidad
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, mat)
            mat = square(mat)
            power //= 2
        return result

    return power(matrix, exp)
