    if n == 0:
        return 1

    blocked_set = set((r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n)

    def backtrack(queens, cols, diag1, diag2):
        if len(queens) == n:
            return 1
        count = 0
        for row in range(n):
            col = len(queens)
            diag1_val = row - col
            diag2_val = row + col
            if (row, col) in blocked_set:
                continue
            if cols[col] or diag1[diag1_val] or diag2[diag2_val]:
                continue
            cols[col] = True
            diag1[diag1_val] = True
            diag2[diag2_val] = True
            count += backtrack(queens + [(row, col)], cols, diag1, diag2)
            cols[col] = False
            diag1[diag1_val] = False
            diag2[diag2_val] = False
        return count

    return backtrack([], [False] * n, [False] * (2 * n - 1), [False] * (2 * n - 1))

