def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    start_date = datetime.strptime(start, "%Y-%m-%d")
    holidays_set = set(datetime.strptime(h, "%Y-%m-%d") for h in holidays)

    def is_business_day(date):
        return date.weekday() < 5 and date not in holidays_set

    current = start_date
    count = 0

    while True:
        current += timedelta(days=1)
        if is_business_day(current):
            count += 1
            if count == abs(n):
                break

    if n < 0:
        current -= timedelta(days=1)
        count = 0
        while True:
            current -= timedelta(days=1)
            if is_business_day(current):
                count += 1
                if count == abs(n):
                    break

    return current.strftime("%Y-%m-%d")
