    import errno

    try:
        with open(log_path, 'a', encoding='utf-8') as f:
            f.write(f"{timestamp} {method} {path} {status}\n")
    except IOError as e:
        if e.errno == errno.ENOENT:
            # File does not exist, create it
            with open(log_path, 'w', encoding='utf-8') as f:
                f.write(f"{timestamp} {method} {path} {status}\n")
        else:
            raise
