def evaluate_expression(expression: str) -> float:
    expression = expression.strip()
    if not expression:
        raise ValueError("Empty expression")

    try:
        # Use Python's eval with restricted environment for security
        import builtins
        import math

        # Define a safe environment with only necessary functions
        safe_env = {
            'math': math,
            '__builtins__': None  # Disable built-in functions to prevent code execution
        }

        # Replace 'math.' with '' to allow direct use of math functions
        expression = expression.replace('math.', '')

        # Evaluate the expression
        result = eval(expression, safe_env)
        return float(result)
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except (SyntaxError, NameError, TypeError, KeyError):
        raise ValueError("Invalid expression")
    except Exception as e:
        raise ValueError("Invalid expression") from e
