import re

def is_local_redirect(target: str, host: str) -> bool:
    # Check for backslash, space, or control characters (ASCII < 32 or == 127)
    if re.search(r'[\x00-\x1f\x7f]', target):
        return False

    # Check if target is a site-relative path
    if target.startswith('/') and (len(target) == 1 or target[1] == '/'):
        return True

    # Check if target starts with http:// or https://
    if target.startswith('http://') or target.startswith('https://'):
        # Parse the host from the URL, ignoring user info and port
        url_parts = target.split('://')
        if len(url_parts) < 2:
            return False
        url_host = url_parts[1].split('@')[0].split(':')[0]
        return url_host.lower() == host.lower()

    return False
