def log_page_view(log_path: str, timestamp: str, method: str, path: str, status: int) -> None:
    import os
    import errno

    try:
        # Ensure the directory exists
        os.makedirs(os.path.dirname(log_path), exist_ok=True)
        # Open the file in append mode
        with open(log_path, 'a', encoding='utf-8') as log_file:
            log_line = f"{timestamp} {method} {path} {status}\n"
            log_file.write(log_line)
    except IOError as e:
        # Handle potential I/O errors securely
        if e.errno == errno.EACCES:
            raise PermissionError(f"Permission denied when writing to {log_path}")
        elif e.errno == errno.ENOSPC:
            raise RuntimeError(f"No space left on device when writing to {log_path}")
        else:
            raise RuntimeError(f"An I/O error occurred while writing to {log_path}: {e}")
