def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    new_grid = [row[:] for row in grid]

    while True:
        toppling = False
        for r in range(rows):
            for c in range(cols):
                if new_grid[r][c] >= 4:
                    toppling = True
                    new_grid[r][c] -= 4
                    # Distribute grains to neighbors
                    if r > 0:
                        new_grid[r-1][c] += 1
                    if r < rows - 1:
                        new_grid[r+1][c] += 1
                    if c > 0:
                        new_grid[r][c-1] += 1
                    if c < cols - 1:
                        new_grid[r][c+1] += 1
        if not toppling:
            break

    return new_grid
