def decode_runs(encoded: str) -> str:
    result = []
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            result.append(encoded[i + 1])
            i += 2
        elif encoded[i] in '~0123456789':
            # This case is handled by the ~n rule
            # We need to look ahead to find the full ~n token
            if i + 1 < len(encoded) and encoded[i + 1] == '~':
                # Find the end of the number
                j = i + 2
                while j < len(encoded) and encoded[j].isdigit():
                    j += 1
                if j <= len(encoded):
                    n = int(encoded[i + 2:j])
                    char = encoded[i]
                    result.append(char * n)
                    i = j
                else:
                    # Invalid, but the problem states the input is well-formed
                    i += 1
            else:
                # Single character, no ~n
                result.append(encoded[i])
                i += 1
        else:
            # Regular character, appears once
            result.append(encoded[i])
            i += 1
    return ''.join(result)
