import re

def identifier_to_snake(name: str) -> str:
    # Split the name into segments using _ and - as separators
    segments = re.split(r'[_-]+', name)
    result = []

    for segment in segments:
        if not segment:
            continue
        # Process the segment to identify word boundaries
        words = []
        i = 0
        while i < len(segment):
            if i + 1 < len(segment) and segment[i].isalpha() and segment[i+1].isalpha():
                # Check if it's between two uppercase letters followed by a lowercase
                if i + 2 < len(segment) and segment[i+1].isupper() and segment[i+2].islower():
                    words.append(segment[i])
                    i += 1
                else:
                    words.append(segment[i])
                    i += 1
            elif i + 1 < len(segment) and segment[i].isalpha() and segment[i+1].isdigit():
                words.append(segment[i])
                i += 1
            elif i + 1 < len(segment) and segment[i].isdigit() and segment[i+1].isalpha():
                words.append(segment[i])
                i += 1
            elif i + 1 < len(segment) and segment[i].islower() and segment[i+1].isupper():
                words.append(segment[i])
                i += 1
            else:
                words.append(segment[i])
                i += 1
        # Join the words with underscores and add to result
        result.append(''.join(words))

    return '_'.join(result)
