import re

def is_valid_email(s: str) -> bool:
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')

    # Validate local part
    local_pattern = r'^[a-zA-Z0-9](?:[a-zA-Z0-9._-]*[a-zA-Z0-9])$'
    if not re.fullmatch(local_pattern, local):
        return False

    # Validate domain part
    domain_parts = domain.split('.')
    if len(domain_parts) < 2:
        return False

    for i, part in enumerate(domain_parts):
        if not part:
            return False
        if i == len(domain_parts) - 1:
            if not re.fullmatch(r'[a-zA-Z]{2,}', part):
                return False
        else:
            if not re.fullmatch(r'[a-zA-Z0-9]+', part):
                return False

    return True
