def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    # Check for items larger than capacity
    for size in sizes:
        if size > capacity:
            raise ValueError("All item sizes must be <= capacity")

    # Sort sizes in descending order
    sizes.sort(reverse=True)

    # List to hold bins
    bins = []

    for size in sizes:
        placed = False
        # Try to place in existing bins
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                placed = True
                break
        # If not placed, create a new bin
        if not placed:
            bins.append([size])

    return bins
