def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number:
        raise ValueError("Invalid input number")

    # Check for negative sign
    is_negative = False
    if number[0] == '-':
        is_negative = True
        number = number[1:]

    # Validate all characters in number
    valid_chars = set("0123456789abcdefghijklmnopqrstuvwxyz")
    for ch in number:
        if ch.lower() not in valid_chars:
            raise ValueError("Invalid character in number")

    # Convert number to decimal
    decimal_value = 0
    for ch in number:
        digit = int(ch) if ch.isdigit() else ord(ch.lower()) - ord('a') + 10
        decimal_value = decimal_value * from_base + digit

    # Handle zero case
    if decimal_value == 0:
        return "0"

    # Convert decimal to target base
    digits = []
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(ord('a') + remainder - 10))
        decimal_value //= to_base

    # Reverse to get correct order
    digits.reverse()

    # Apply negative sign if needed
    if is_negative:
        digits.insert(0, '-')

    return ''.join(digits)
