from collections import deque
import sys

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None

    # Find start and end positions
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[[False] * (cols + 1) for _ in range(rows + 1)] for _ in range(3)]

    queue = deque()
    queue.append((start[0], start[1], 0, 0))  # (row, col, steps, wall_breaks)
    visited[0][start[0]][start[1]] = True

    while queue:
        r, c, steps, breaks = queue.popleft()

        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '#':
                    if breaks < 1 and not visited[1][nr][nc]:
                        visited[1][nr][nc] = True
                        queue.append((nr, nc, steps + 1, breaks + 1))
                else:
                    if not visited[0][nr][nc]:
                        visited[0][nr][nc] = True
                        queue.append((nr, nc, steps + 1, breaks))

    return -1
