from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None

    # Find start and end positions
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS queue: (row, col, breaks_used, steps)
    queue = deque([(start[0], start[1], 0, 0)])
    visited = set()
    visited.add((start[0], start[1], 0))

    while queue:
        r, c, breaks, steps = queue.popleft()

        # Check if we reached the end
        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # Check if the new position is within bounds
            if 0 <= nr < rows and 0 <= nc < cols:
                cell = grid[nr][nc]

                # If it's a wall and we haven't used a break yet
                if cell == '#' and breaks < 1:
                    new_breaks = breaks + 1
                    if (nr, nc, new_breaks) not in visited:
                        visited.add((nr, nc, new_breaks))
                        queue.append((nr, nc, new_breaks, steps + 1))
                # If it's a normal cell or we already broke once
                elif cell != '#':
                    if (nr, nc, breaks) not in visited:
                        visited.add((nr, nc, breaks))
                        queue.append((nr, nc, breaks, steps + 1))

    return -1
