from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None

    # Find start and end positions
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS with state (row, col, break_used)
    queue = deque([(start[0], start[1], 0)])
    visited = set()
    visited.add((start[0], start[1], 0))

    while queue:
        r, c, breaks = queue.popleft()

        if (r, c) == end:
            return breaks

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                cell = grid[nr][nc]
                if cell == '#':
                    if breaks < 1:
                        new_state = (nr, nc, breaks + 1)
                        if new_state not in visited:
                            visited.add(new_state)
                            queue.append(new_state)
                else:
                    new_state = (nr, nc, breaks)
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append(new_state)

    return -1
