import re

def is_valid_email(s: str) -> bool:
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')

    # Validate local part
    if not re.fullmatch(r'[a-zA-Z0-9._-]+', local):
        return False
    if not (local[0].isalnum() and local[-1].isalnum()):
        return False
    if '..' in local or '__' in local or '--' in local:
        return False

    # Validate domain part
    if '.' not in domain:
        return False
    parts = domain.split('.')
    if len(parts) != 2:
        return False
    if not (parts[0].isalnum() and parts[1].isalpha()):
        return False
    if len(parts[1]) < 2:
        return False

    return True
