import os
from http import HTTPStatus

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # Normalize the request path
    normalized_path = os.path.normpath(request_path)

    # Check if the path is a directory or if it's the root
    if normalized_path == '/':
        file_path = os.path.join(web_root, 'index.html')
    else:
        # Remove leading '/' and append to web_root
        file_path = os.path.join(web_root, normalized_path[1:])

    # Check if the file exists and is a regular file
    if os.path.isfile(file_path):
        with open(file_path, 'rb') as f:
            content = f.read()
        return (HTTPStatus.OK.value, content)
    else:
        return (HTTPStatus.NOT_FOUND.value, b"Not Found")
