import yaml
from typing import List, Dict

def parse_jobs(text: str) -> List[Dict]:
    if not text.strip():
        return []
    try:
        data = yaml.safe_load(text)
        if not isinstance(data, list):
            return []
        jobs = []
        for job in data:
            if not isinstance(job, dict):
                continue
            name = job.get('name')
            interval = job.get('interval')
            enabled = job.get('enabled', True)
            if name is None or not isinstance(name, str) or not isinstance(interval, int):
                continue
            jobs.append({'name': name, 'interval': interval, 'enabled': enabled})
        return jobs
    except yaml.YAMLError:
        return []
