import re
import math

def evaluate_expression(expression: str) -> float:
    expression = expression.strip()
    if not expression:
        raise ValueError("Empty expression")

    # Remove all whitespace
    expression = re.sub(r'\s+', '', expression)

    # Check for balanced parentheses
    if expression.count('(') != expression.count(')'):
        raise ValueError("Unbalanced parentheses")

    # Check for invalid characters
    if re.search(r'[^0-9.+\-*/()**]', expression):
        raise ValueError("Invalid character in expression")

    # Replace ** with ** for Python's exponentiation
    expression = re.sub(r'\*\*', '**', expression)

    # Check for unary minus
    # Find positions where a '-' is not preceded by a number, '(' or operator
    unary_minus_positions = [m.start() for m in re.finditer(r'(?<![\d\(\+\-\*\/])-', expression)]
    for pos in unary_minus_positions:
        expression = expression[:pos] + '0' + expression[pos:]

    # Evaluate the expression using Python's eval with restricted namespace
    try:
        result = eval(expression, {"__builtins__": None}, {
            'math': math,
            '+': lambda a, b: a + b,
            '-': lambda a, b: a - b,
            '*': lambda a, b: a * b,
            '/': lambda a, b: a / b if b != 0 else float('inf'),
            '**': lambda a, b: a ** b,
        })
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except Exception as e:
        raise ValueError("Invalid expression") from e

    return float(result)

