def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    from itertools import permutations

    # Create a set of conflict pairs for quick lookup
    conflict_set = set()
    for a, b in conflicts:
        conflict_set.add(frozenset({a, b}))

    # Generate all permutations of guests
    all_perms = permutations(guests)

    # Filter permutations to exclude those with conflicting adjacent guests
    valid_perms = []
    for perm in all_perms:
        valid = True
        for i in range(len(perm) - 1):
            pair = frozenset({perm[i], perm[i + 1]})
            if pair in conflict_set:
                valid = False
                break
        if valid:
            valid_perms.append(list(perm))

    return valid_perms

