def decode_runs(encoded: str) -> str:
    i = 0
    result = []
    while i < len(encoded):
        if encoded[i] == '\\':
            i += 1
            if i < len(encoded) and encoded[i] == '~':
                i += 1
                num_str = ''
                while i < len(encoded) and encoded[i].isdigit():
                    num_str += encoded[i]
                    i += 1
                repeat = int(num_str) if num_str else 0
                if repeat > 0:
                    result.append(encoded[i - 1] * repeat)
            else:
                result.append(encoded[i])
                i += 1
        else:
            result.append(encoded[i])
            i += 1
    return ''.join(result)
