import re
from urllib.parse import urlparse

def is_local_redirect(target: str, host: str) -> bool:
    if not target or not host:
        return False

    # Check for invalid characters
    if any(c in r'\\ \t\n\r\x0b\x0c' for c in target):
        return False

    # Check for site-relative path
    if target.startswith('/') and len(target) > 1 and target[1] != '/':
        return True

    # Check for absolute URL with matching host
    try:
        parsed = urlparse(target)
        if parsed.scheme not in ('http', 'https'):
            return False
        url_host = parsed.netloc.lower()
        host = host.lower()
        return url_host == host
    except:
        return False
