def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    conflict_set = set()
    for a, b in conflicts:
        conflict_set.add((a, b))
        conflict_set.add((b, a))

    n = len(guests)
    result = []

    def backtrack(path, used):
        if len(path) == n:
            result.append(path.copy())
            return
        for i in range(n):
            if not used[i]:
                current_guest = guests[i]
                valid = True
                for j in range(len(path)):
                    neighbor = path[j]
                    if (current_guest, neighbor) in conflict_set or (neighbor, current_guest) in conflict_set:
                        valid = False
                        break
                if valid:
                    path.append(current_guest)
                    used[i] = True
                    backtrack(path, used)
                    path.pop()
                    used[i] = False

    used = [False] * n
    backtrack([], used)
    return sorted(result)
```

