def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number:
        raise ValueError("Invalid number")
    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    # Validate input number
    for ch in number:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or 'A' <= ch <= 'Z'):
            raise ValueError("Invalid character in number")

    # Convert to lowercase
    number = number.lower()

    # Check if all characters are valid in from_base
    for ch in number:
        if ch.isdigit():
            digit = int(ch)
        else:
            digit = ord(ch) - ord('a') + 10
        if digit >= from_base:
            raise ValueError("Invalid character for from_base")

    # Convert number to decimal
    decimal = 0
    for ch in number:
        if ch.isdigit():
            digit = int(ch)
        else:
            digit = ord(ch) - ord('a') + 10
        decimal = decimal * from_base + digit

    # Handle zero
    if decimal == 0:
        return '0'

    # Convert decimal to to_base
    if decimal < 0:
        is_negative = True
        decimal = -decimal

    result = ''
    while decimal > 0:
        if decimal % to_base < 10:
            result = str(decimal % to_base) + result
        else:
            result = chr(ord('a') + decimal % to_base - 10) + result
        decimal = decimal // to_base

    if is_negative:
        result = '-' + result
    return result
