def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    for size in sizes:
        if size > capacity:
            raise ValueError("All elements must be <= capacity")

    bins = []
    for size in sorted(sizes, reverse=True):
        placed = False
        for i in range(len(bins)):
            if sum(bins[i]) + size <= capacity:
                bins[i].append(size)
                placed = True
                break
        if not placed:
            bins.append([size])
    return bins
