from urllib.parse import urlparse

def is_local_redirect(target: str, host: str) -> bool:
    if any(c in target for c in ['\\', ' ', '\x00', '\x01', '\x02', '\x03', '\x04', '\x05', '\x06', '\x07', '\x08', '\x0b', '\x0c', '\x0e', '\x0f', '\x10', '\x11', '\x12', '\x13', '\x14', '\x15', '\x16', '\x17', '\x18', '\x19', '\x1a', '\x1b', '\x1c', '\x1d', '\x1e', '\x1f']):
        return False
    if target.startswith('/'):
        return len(target) > 1 and target[1] != '/'
    try:
        parsed = urlparse(target)
        if parsed.scheme not in ('http', 'https'):
            return False
        netloc = parsed.netloc
        if not netloc:
            return False
        return netloc.lower() == host.lower()
    except:
        return False
