def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    conflict_set = set()
    for a, b in conflicts:
        conflict_set.add((a, b))
        conflict_set.add((b, a))

    result = []

    def backtrack(path, used):
        if len(path) == len(guests):
            result.append(path.copy())
            return
        for guest in guests:
            if guest not in used:
                valid = True
                for prev in path:
                    if (prev, guest) in conflict_set or (guest, prev) in conflict_set:
                        valid = False
                        break
                if valid:
                    path.append(guest)
                    used.add(guest)
                    backtrack(path, used)
                    path.pop()
                    used.remove(guest)

    backtrack([], set())
    result.sort()
    return result if result else [[]]
