def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or not all(c in '0123456789abcdefghijklmnopqrstuvwxyz' for c in number.lower()):
        raise ValueError

    # Handle negative numbers
    is_negative = number.startswith('-')
    if is_negative:
        number = number[1:]

    # Convert from base to decimal
    decimal_value = 0
    for digit in number:
        decimal_value = decimal_value * from_base + (int(digit) if digit.isdigit() else ord(digit.lower()) - ord('a') + 10)

    # Handle zero case
    if decimal_value == 0:
        return '0'

    # Convert from decimal to target base
    digits = []
    while decimal_value > 0:
        remainder = decimal_value % to_base
        digits.append(str(remainder) if remainder < 10 else chr(ord('a') + remainder - 10))
        decimal_value //= to_base

    # Reverse to get correct order
    digits = digits[::-1]

    # Add negative sign if needed
    if is_negative:
        return '-' + ''.join(digits)
    else:
        return ''.join(digits)
