import ast
import builtins

def matches_filter(expression: str, record: dict) -> bool:
    try:
        # Create a new namespace with the record's keys as variables
        namespace = {key: value for key, value in record.items()}
        # Add built-in functions and types to the namespace
        namespace.update({k: v for k, v in builtins.__dict__.items() if not k.startswith('__')})

        # Parse and evaluate the expression
        tree = ast.parse(expression, mode='eval')
        # Replace all occurrences of the record's keys with their values in the AST
        for node in ast.walk(tree):
            if isinstance(node, ast.Name) and node.id in namespace:
                node.id = str(namespace[node.id])
        result = eval(compile(tree, '<string>', 'eval'))
        return result
    except (SyntaxError, NameError, KeyError, TypeError, AttributeError):
        raise ValueError("Invalid expression or unknown name in expression")
