def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Filter out invalid busy intervals
    valid_busy = [(s, e) for s, e in busy if s < e]

    # Sort the valid busy intervals by start time
    valid_busy.sort()

    # Add the day start and end as virtual boundaries
    free_intervals = []
    prev_end = day_start

    for start, end in valid_busy:
        if start > prev_end:
            # There is a free interval between prev_end and start
            if start - prev_end >= min_len:
                free_intervals.append((prev_end, start))
        prev_end = max(prev_end, end)

    # Check the last interval after the last busy interval
    if day_end > prev_end and day_end - prev_end >= min_len:
        free_intervals.append((prev_end, day_end))

    return free_intervals

