def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or len(matrix) == 0:
        return []
    n = len(matrix)
    result = [[0]*n for _ in range(n)]
    for layer in range((n + 1) // 2):
        start = layer
        end = n - 1 - layer
        ring_length = (end - start) * 2 + 1
        k = k % ring_length
        if k == 0:
            for i in range(start, end + 1):
                for j in range(start, end + 1):
                    result[i][j] = matrix[i][j]
            continue
        # Collect elements in the ring
        ring = []
        for j in range(start, end + 1):
            ring.append(matrix[start][j])
        for i in range(start + 1, end + 1):
            ring.append(matrix[i][end])
        for j in range(end - 1, start - 1, -1):
            ring.append(matrix[end][j])
        for i in range(end - 1, start, -1):
            ring.append(matrix[i][start])
        # Rotate the ring
        rotated_ring = ring[-k:] + ring[:-k]
        # Place rotated elements back
        idx = 0
        for j in range(start, end + 1):
            result[start][j] = rotated_ring[idx]
            idx += 1
        for i in range(start + 1, end + 1):
            result[i][end] = rotated_ring[idx]
            idx += 1
        for j in range(end - 1, start - 1, -1):
            result[end][j] = rotated_ring[idx]
            idx += 1
        for i in range(end - 1, start, -1):
            result[i][start] = rotated_ring[idx]
            idx += 1
    return result
