def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    # Filter out invalid busy intervals
    valid_busy = [interval for interval in busy if interval[0] < interval[1]]

    # Sort valid busy intervals by start time
    valid_busy.sort()

    # Initialize result list
    free_slots = []

    # Add the time before the first busy interval
    if valid_busy:
        first_start = valid_busy[0][0]
        if day_start < first_start:
            free_slots.append((day_start, first_start))
    else:
        # If no busy intervals, the whole day is free
        if day_end - day_start >= min_len:
            free_slots.append((day_start, day_end))
        return free_slots

    # Check between busy intervals
    for i in range(1, len(valid_busy)):
        prev_end = valid_busy[i-1][1]
        curr_start = valid_busy[i][0]
        if curr_start > prev_end:
            if curr_start - prev_end >= min_len:
                free_slots.append((prev_end, curr_start))

    # Add the time after the last busy interval
    last_end = valid_busy[-1][1]
    if last_end < day_end:
        if day_end - last_end >= min_len:
            free_slots.append((last_end, day_end))

    return free_slots
