            free_slots.append((day_start, day_end))
        return free_slots

    # Check between busy intervals
    for i in range(1, len(valid_busy)):
        prev_end = valid_busy[i-1][1]
        curr_start = valid_busy[i][0]
        if curr_start > prev_end:
            if curr_start - prev_end >= min_len:
                free_slots.append((prev_end, curr_start))

    # Add the time after the last busy interval
    last_end = valid_busy[-1][1]
    if last_end < day_end:
        if day_end - last_end >= min_len:
            free_slots.append((last_end, day_end))

    return free_slots

