    if not number:
        raise ValueError("number cannot be empty")
    if number == '-':
        raise ValueError("number cannot be just '-'")

    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if from_base < 2 or from_base > 36:
        raise ValueError("from_base must be between 2 and 36")
    if to_base < 2 or to_base > 36:
        raise ValueError("to_base must be between 2 and 36")

    # Check if all characters in number are valid for from_base
    for c in number.lower():
        if c not in digits[:from_base]:
            raise ValueError("invalid character in number")

    # Handle negative numbers
    is_negative = number[0] == '-'
    if is_negative:
        number = number[1:]

    # Convert from from_base to decimal
    decimal_value = 0
    for c in number:
        decimal_value = decimal_value * from_base + digits.index(c)

    # Handle zero case
    if decimal_value == 0:
        return '0'

    # Convert from decimal to to_base
    result = ''
    while decimal_value > 0:
        remainder = decimal_value % to_base
        result = digits[remainder] + result
        decimal_value //= to_base

    # Add negative sign if needed
    if is_negative:
        result = '-' + result

    return result
