def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit descending, and by original order for equal profits
    sorted_jobs = sorted(jobs, key=lambda x: (-x[2], jobs.index(x)))
    slots = {}

    for name, deadline, _ in sorted_jobs:
        # Find the highest-numbered slot <= deadline that is still free
        for slot in range(deadline, 0, -1):
            if slot not in slots:
                slots[slot] = name
                break

    # Prepare the result in order of slot numbers
    result = [f"{name} {slot}" for slot, name in sorted(slots.items())]
    return result
