def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by descending profit, and then by original order for ties
    sorted_jobs = sorted(jobs, key=lambda x: (-x[1], jobs.index(x)))
    slots = {}
    result = []

    for name, deadline, _ in sorted_jobs:
        if deadline < 1:
            continue
        # Find the highest-numbered free slot not exceeding the deadline
        slot = None
        for s in range(deadline, 0, -1):
            if s not in slots:
                slot = s
                break
        if slot is not None:
            slots[slot] = name
            result.append(name)

    # Sort the result by slot number
    return [slots[slot] for slot in sorted(slots.keys())]
