import re
import ast

def matches_filter(expression: str, record: dict) -> bool:
    try:
        # Validate that all variables in the expression exist in the record
        variables = re.findall(r'\b([a-zA-Z_]\w*)\b', expression)
        for var in variables:
            if var not in record:
                raise ValueError(f"Variable '{var}' not found in record")

        # Parse the expression into an AST
        tree = ast.parse(expression, mode='eval')

        # Replace variable names with their corresponding values from the record
        class ReplaceVisitor(ast.NodeTransformer):
            def visit_Name(self, node):
                if isinstance(node.ctx, ast.Load) and node.id in record:
                    return ast.Constant(value=record[node.id])
                return node

        tree = ReplaceVisitor().visit(tree)

        # Evaluate the modified AST
        result = eval(compile(tree, filename="<ast>", mode='eval'))
        return result
    except (SyntaxError, ValueError, KeyError, TypeError, NameError):
        raise ValueError("Invalid expression or unknown variable in expression")
