def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine column widths
    col_widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    # Format each row based on alignment
    formatted_rows = []
    for row in rows:
        formatted_cells = []
        for i, cell in enumerate(row):
            width = col_widths[i]
            if aligns[i] == 'l':
                formatted_cells.append(cell.ljust(width))
            elif aligns[i] == 'r':
                formatted_cells.append(cell.rjust(width))
            elif aligns[i] == 'c':
                formatted_cells.append(cell.center(width))
        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
