def expand_template(template: str, values: dict[str, str]) -> str:
    result = []
    i = 0
    n = len(template)
    while i < n:
        if i + 1 < n and template[i:i+2] == '{{':
            result.append('{')
            i += 2
        elif i + 1 < n and template[i:i+2] == '}}':
            result.append('}')
            i += 2
        elif template[i] == '{':
            start = i
            i += 1
            while i < n and template[i] != '}':
                i += 1
            if i < n:
                key = template[start+1:i]
                if key in values:
                    result.append(values[key])
                else:
                    result.append(template[start:i+1])
                i += 1
            else:
                result.append(template[start:i+1])
                i += 1
        else:
            result.append(template[i])
            i += 1
    return ''.join(result)
