import math
import re
import ast

def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the actual value
    formula = formula.replace('x', str(x))

    # Define a custom function for sqrt, abs, sin, cos
    def custom_eval(node):
        if isinstance(node, ast.Expression):
            return custom_eval(node.body)
        elif isinstance(node, ast.UnaryOp):
            op = node.op
            if isinstance(op, ast.USub):
                return -custom_eval(node.operand)
            else:
                raise ValueError("Unsupported unary operation")
        elif isinstance(node, ast.BinOp):
            left = custom_eval(node.left)
            right = custom_eval(node.right)
            op = node.op
            if isinstance(op, ast.Add):
                return left + right
            elif isinstance(op, ast.Sub):
                return left - right
            elif isinstance(op, ast.Mult):
                return left * right
            elif isinstance(op, ast.Div):
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                return left / right
            elif isinstance(op, ast.Pow):
                return left ** right
            else:
                raise ValueError("Unsupported binary operation")
        elif isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Name):
                func_name = func.id
                if func_name == 'sqrt':
                    if len(node.args) != 1:
                        raise ValueError("sqrt requires exactly one argument")
                    arg = custom_eval(node.args[0])
                    if arg < 0:
                        raise ValueError("sqrt of negative number")
                    return math.sqrt(arg)
                elif func_name == 'abs':
                    if len(node.args) != 1:
                        raise ValueError("abs requires exactly one argument")
                    return abs(custom_eval(node.args[0]))
                elif func_name == 'sin':
                    if len(node.args) != 1:
                        raise ValueError("sin requires exactly one argument")
                    return math.sin(custom_eval(node.args[0]))
                elif func_name == 'cos':
                    if len(node.args) != 1:
                        raise ValueError("cos requires exactly one argument")
                    return math.cos(custom_eval(node.args[0]))
                else:
                    raise ValueError(f"Unknown function: {func_name}")
            else:
                raise ValueError("Unsupported function call")
        elif isinstance(node, ast.Name):
            if node.id == 'x':
                return x
            else:
                raise ValueError(f"Unknown variable: {node.id}")
        elif isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Compare):
            # For simplicity, we only handle equality here
            left = custom_eval(node.left)
            right = custom_eval(node.right)
            op = node.ops[0]
            if isinstance(op, ast.Eq):
                return left == right
            else:
                raise ValueError("Unsupported comparison")
        else:
            raise ValueError(f"Unsupported node type: {type(node)}")

    # Parse the formula into an AST
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid formula syntax")

    # Check for invalid functions or variables
    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            if node.id not in {'x', 'sqrt', 'abs', 'sin', 'cos'}:
                raise ValueError(f"Unknown variable or function: {node.id}")

    # Evaluate the formula
    try:
        result = custom_eval(tree)
    except ZeroDivisionError as e:
        raise ZeroDivisionError("division by zero") from e
    except Exception as e

