import math
import re
import sys
import ast

def evaluate_formula(formula: str, x: float) -> float:
    try:
        # Replace 'x' with the actual value
        formula = formula.replace('x', str(x))

        # Define custom functions for math operations
        def sqrt_func(arg):
            return math.sqrt(arg)

        def abs_func(arg):
            return abs(arg)

        def sin_func(arg):
            return math.sin(arg)

        def cos_func(arg):
            return math.cos(arg)

        # Replace function names with lambda expressions
        formula = re.sub(r'sqrt\((.*?)\)', r'sqrt_func(\1)', formula)
        formula = re.sub(r'abs\((.*?)\)', r'abs_func(\1)', formula)
        formula = re.sub(r'sin\((.*?)\)', r'sin_func(\1)', formula)
        formula = re.sub(r'cos\((.*?)\)', r'cos_func(\1)', formula)

        # Parse the formula using AST to ensure safety
        node = ast.parse(formula, mode='eval')

        # Evaluate the parsed expression
