def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source:
        return []

    # Define regex patterns for each token type
    number_pattern = r'\d+(?:\.\d+)?'
    name_pattern = r'[a-zA-Z_][a-zA-Z0-9_]*'
    op_pattern = r'==|!=|<=|>=|[+\-*/<>=() ,]'

    # Combine all patterns into one regex
    token_pattern = re.compile(f'({number_pattern})|({name_pattern})|({op_pattern})')

    tokens = []
    pos = 0
    while pos < len(source):
        match = token_pattern.match(source, pos)
        if not match:
            # Check for invalid characters
            if re.search(r'[^a-zA-Z0-9_+\-*/<>=() ,.]', source[pos:]):
                raise ValueError("Invalid character in source")
            break
        token = match.group()
        if token:
            # Determine token type
            if re.fullmatch(number_pattern, token):
                tokens.append(('NUMBER', token))
            elif re.fullmatch(name_pattern, token):
                tokens.append(('NAME', token))
            elif re.fullmatch(op_pattern, token):
                tokens.append(('OP', token))
            pos += len(token)

    return tokens

