def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source:
        return []

    # Define regex patterns for each token type
    patterns = [
        (r'==|!=|<=|>=|[-+*/<>=() ,]', 'OP'),
        (r'\d+\.\d+|\d+', 'NUMBER'),
        (r'[a-zA-Z_][a-zA-Z0-9_]*', 'NAME'),
    ]

    # Combine patterns into a single regex
    token_pattern = '|'.join(f'({pattern})' for pattern, _ in patterns)
    token_regex = re.compile(token_pattern)

    # Find all matches in the source code
    tokens = token_regex.finditer(source)

    # Process each token
    result = []
    for token in tokens:
        text = token.group(0)
        # Check if the token is a multi-character operator
        if len(text) > 1:
            # Check if the operator is valid
            if text not in ('==', '!=', '<=', '>='):
                raise ValueError(f"Invalid operator: {text}")
        else:
            # Check if the single-character operator is valid
            if text not in ('+', '-', '*', '/', '<', '>', '=', '(', ')', ','):
