def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine column widths
    col_widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    # Format each cell based on alignment
    def format_cell(text: str, width: int, align: str) -> str:
        if align == 'l':
            return text.ljust(width)
        elif align == 'r':
            return text.rjust(width)
        elif align == 'c':
            return text.center(width)
        else:
            raise ValueError("Invalid alignment character")

    # Format each row
    formatted_rows = []
    for i, row in enumerate(rows):
        formatted_row = []
        for j, text in enumerate(row):
            formatted_row.append(format_cell(text, col_widths[j], aligns[j]))
        formatted_rows.append(" | ".join(formatted_row))

    return "\n".join(formatted_rows)
