def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Filtrar y ordenar los intervalos ocupados
    busy = [(s, e) for s, e in busy if s < e]
    busy.sort()

    # Añadir el día completo como un intervalo para comparar
    busy.append((day_start, day_end))

    free = []
    prev_end = day_start

    for start, end in busy:
        if prev_end < start:
            if start - prev_end >= min_len:
                free.append((prev_end, start))
        prev_end = max(prev_end, end)

    # Eliminar el intervalo del día completo si estaba en la lista
    if (day_start, day_end) in busy:
        free = [slot for slot in free if not (slot[0] == day_start and slot[1] == day_end)]

    return free

