import re
import ast
from typing import Dict, Any

def matches_filter(expression: str, record: Dict[str, Any]) -> bool:
    # Check if all variables in the expression are keys in the record
    variables = re.findall(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\b', expression)
    for var in set(variables):
        if var not in record:
            raise ValueError(f"Unknown variable: {var}")

    # Replace variables with their values in the expression
    for key in record:
        expression = expression.replace(key, str(record[key]))

    # Try to parse the expression as a boolean expression
    try:
        node = ast.parse(expression, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid expression syntax")

    # Check if the expression is a boolean expression
    if not isinstance(node.body, (ast.Compare, ast.BoolOp, ast.UnaryOp, ast.Name, ast.Constant)):
        raise ValueError("Invalid expression")

    # Evaluate the expression
    try:
        return eval(compile(node, '<string>', 'eval'), {}, {})
    except Exception as e:
        raise ValueError("Invalid expression") from e
