import re
import ast
import builtins

def matches_filter(expression: str, record: dict) -> bool:
    # Check if all variables in the expression are keys in the record
    variables = re.findall(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\b', expression)
    for var in variables:
        if var not in record:
            raise ValueError(f"Variable '{var}' not found in record")

    # Replace variables in the expression with their values from the record
    for key in record:
        expression = expression.replace(key, str(record[key]))

    # Check if the expression is valid and evaluate it
    try:
        node = ast.parse(expression, mode='eval')
        # Replace built-in functions with dummy ones to prevent unintended behavior
        for node in ast.walk(node):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
                if node.func.id in dir(builtins):
                    raise ValueError("Built-in functions are not allowed in the expression")
        result = eval(compile(node, '<string>', 'eval'), {}, {})
        return bool(result)
    except (SyntaxError, NameError, TypeError, ValueError):
        raise ValueError("Invalid expression")
