import re
import ast

def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the actual value
    formula = formula.replace('x', str(x))

    # Define a custom math functions dictionary
    math_functions = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    # Replace math function calls with their corresponding names
    for func_name, func in math_functions.items():
        formula = formula.replace(f'({func_name}(', f'({func_name}(')

    # Check if the formula is valid
    try:
        # Parse the formula using AST to check for syntax errors
        ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid formula syntax")

    # Check for invalid variable names
    if re.search(r'[^x\s\+\-\*\/\(\)\.\d\-\+\*\/\$\^\s]', formula):
        raise ValueError("Formula contains invalid characters")

    # Check for invalid function names
    if re.search(r'([a-zA-Z_][a-zA-Z0-9_]*)\b(?!\w)', formula):
        raise ValueError("Formula contains invalid function names")

    # Evaluate the formula
    try:
        result = eval(formula, {'__builtins__': None}, math_functions)
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except Exception as e:
        raise ValueError("Invalid formula") from e

    return float(result)
