from urllib.parse import urlparse

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    try:
        parsed = urlparse(url)
        if parsed.scheme not in ('http', 'https'):
            return False
        host = parsed.hostname
        if not host:
            return False
        # Convert to lowercase and remove trailing dot if present
        normalized_host = host.lower().rstrip('.')
        # Check if normalized host is in allowed hosts (also normalized)
        allowed = [h.lower() for h in allowed_hosts]
        return normalized_host in allowed
    except Exception:
        return False

