def evaluate_formula(formula: str, x: float) -> float:
    # Replace variable x with its value
    formula = formula.replace('x', str(x))

    # Define allowed functions
    allowed_functions = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    # Replace function calls with their corresponding math functions
    for func_name, func in allowed_functions.items():
        formula = re.sub(rf'({func_name})\(([^)]+)\)', lambda m: str(func(float(m.group(2)))), formula)

    # Check for invalid characters
    if re.search(r'[^0-9.+\-*/\(\)\sxa-zA-Z]', formula):
        raise ValueError("Invalid characters in formula")

    # Check for invalid function names
    if re.search(r'\b([a-zA-Z]+)\b', formula):
        func_names = re.findall(r'\b([a-zA-Z]+)\b', formula)
        for name in func_names:
            if name not in allowed_functions and name != 'x':
                raise ValueError("Invalid function or variable name")

    # Evaluate the formula
    try:
        result = eval(formula, {"__builtins__": None}, {"math": math, "abs": abs, "x": x})
        return float(result)
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
