def evaluate_formula(formula: str, x: float) -> float:
    # Replace function names with their corresponding math functions
    formula = formula.replace('sqrt', 'math.sqrt')
    formula = formula.replace('abs', 'math.abs')
    formula = formula.replace('sin', 'math.sin')
    formula = formula.replace('cos', 'math.cos')

    # Replace 'x' with the variable name used in the AST
    formula = formula.replace('x', 'var')

    # Define a custom AST visitor to replace 'var' with the actual x value
    class VarReplacer(ast.NodeTransformer):
        def visit_Name(self, node):
            if node.id == 'var':
                node.id = 'x'
            return self.generic_visit(node)

    # Parse the formula into an AST
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid formula syntax")

    # Replace 'var' with 'x' in the AST
    VarReplacer().visit(tree)

    # Compile and evaluate the AST
    try:
        result = eval(compile(tree, '<formula>', 'eval'), {'math': math, 'x': x})
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except Exception as e:
        raise ValueError("Invalid formula") from e

    return float(result)
