def parse_csv(text: str) -> list[list[str]]:
    if not text:
        return []

    lines = text.strip('\n').split('\n')
    result = []

    for line in lines:
        fields = []
        i = 0
        while i < len(line):
            if line[i] == '"':
                # Start of a quoted field
                i += 1
                field = ''
                while i < len(line):
                    if line[i] == '"':
                        i += 1
                        if i < len(line) and line[i] == '"':
                            # Two consecutive quotes, replace with one
                            field += '"'
                            i += 1
                        else:
                            # End of quoted field
                            break
                    elif line[i] == ',' and i < len(line) - 1 and line[i+1] == '"':
                        # Comma followed by a quote, part of a quoted field
                        i += 1
                    else:
                        field += line[i]
                        i += 1
                fields.append(field)
            elif line[i] == ',':
                # Separator, move to next field
                i += 1
            else:
                # Unquoted field
                j = i
                while j < len(line) and line[j] != ',':
                    j += 1
                fields.append(line[i:j])
                i = j
        result.append(fields)

    return result
