        # Check if the formula contains any invalid operators
        if re.search(r'[^0-9.+\-*/\(\)\^]', formula_with_x):
            raise ValueError("Invalid formula: contains invalid characters")

        # Evaluate the formula using sympy to handle mathematical operations securely
        expr = sympy.sympify(formula_with_x)
        result = expr.evalf()

        # Check for division by zero
        if result == float('inf') or result == -float('inf'):
            raise ZeroDivisionError("Division by zero")

        return float(result)

    except ZeroDivisionError as e:
        raise e
    except Exception as e:
        raise ValueError("Invalid formula: syntax error or invalid expression") from e
