import sys

def matches_filter(expression: str, record: dict) -> bool:
    class RestrictedDict(dict):
        def __init__(self, record):
            super().__init__(record)

        def __getitem__(self, key):
            if key not in self:
                raise KeyError(f"Key '{key}' not found in record")
            return super().__getitem__(key)

    class RestrictedNamespace:
        def __init__(self, record):
            self.record = RestrictedDict(record)

        def __getattr__(self, name):
            if name in self.record:
                return self.record[name]
            raise AttributeError(f"Name '{name}' not found in record")

    try:
        # Create a restricted namespace with only the record's keys
        ns = RestrictedNamespace(record)
        # Add built-in functions and types that are safe to use
        ns.__builtins__ = {
            'int': int,
            'float': float,
            'str': str,
            'bool': bool,
            'len': len,
            'abs': abs,
            'min': min,
            'max': max,
            'sum': sum,
            'any': any,
            'all': all,
            'not': not,
            'and': and,
            'or': or,
            'True': True,
            'False': False,
            'None': None
        }
        # Parse and evaluate the expression safely
        tree = ast.parse(expression, mode='eval')
        # Check for disallowed names
        for node in ast.walk(tree):
            if isinstance(node, ast.Name):
                if node.id not in ns.record and node.id not in ns.__builtins__:
                    raise ValueError(f"Invalid name '{node.id}' in expression")
        # Evaluate the expression in the restricted namespace
        result = eval(tree, ns.__builtins__, ns)
        return result
    except (SyntaxError, ValueError, KeyError, AttributeError, NameError, TypeError, IndexError, OverflowError):
        raise ValueError("Invalid expression or unknown name in filter")
