import re

def matches_filter(expression: str, record: dict) -> bool:
    # Validate that all variables in the expression are present in the record
    variables = re.findall(r'\b([a-zA-Z_]\w*)\b', expression)
    for var in variables:
        if var not in record:
            raise ValueError(f"Variable '{var}' not found in record")

    # Create a new namespace with the record's variables and built-in functions
    namespace = {
        **record,
        **{k: v for k, v in builtins.__dict__.items() if not k.startswith('__')}
    }

    # Parse the expression safely using AST
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid expression syntax")

    # Check for disallowed operations or attributes
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name):
                if node.func.id in {'eval', 'exec', 'input', 'open', 'exit', 'exitshell', 'system'}:
                    raise ValueError("Disallowed function call in expression")
            elif isinstance(node.func, ast.Attribute):
                if node.func.attr in {'__import__', 'eval', 'exec', 'input', 'open', 'exit', 'exitshell', 'system'}:
                    raise ValueError("Disallowed attribute access in expression")

    # Evaluate the expression in the restricted namespace
    try:
        result = eval(compile(tree, '<string>', 'eval'), namespace)
    except Exception as e:
        raise ValueError("Invalid expression") from e

    return result
