def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    while i < len(source):
        if source[i].isspace():
            i += 1
            continue
        if re.match(r'[0-9]', source[i]):
            # Match number
            num = ''
            while i < len(source) and re.match(r'[0-9]', source[i]):
                num += source[i]
                i += 1
            if i < len(source) and source[i] == '.':
                num += source[i]
                i += 1
                if i < len(source) and re.match(r'[0-9]', source[i]):
                    num += source[i]
                    i += 1
                else:
                    raise ValueError("Invalid number format")
            tokens.append(('NUMBER', num))
        elif re.match(r'[a-zA-Z_]', source[i]):
            # Match name
            name = ''
            while i < len(source) and (re.match(r'[a-zA-Z0-9_]', source[i])):
                name += source[i]
                i += 1
            tokens.append(('NAME', name))
        elif source[i] in '+-*/<>=(),':
            # Match single-character operator
            tokens.append(('OP', source[i]))
            i += 1
        elif source[i] == '=' and i + 1 < len(source) and source[i+1] == '=':
            # Match == operator
            tokens.append(('OP', '=='))
            i += 2
        elif source[i] == '!' and i + 1 < len(source) and source[i+1] == '=':
            # Match != operator
            tokens.append(('OP', '!='))
            i += 2
        elif source[i] == '<' and i + 1 < len(source) and source[i+1] == '=':
            # Match <= operator
            tokens.append(('OP', '<='))
            i += 2
        elif source[i] == '>' and i + 1 < len(source) and source[i+1] == '=':
            # Match >= operator
            tokens.append(('OP', '>='))
            i += 2
        else:
            raise ValueError(f"Invalid character: {source[i]}")
    return tokens

