def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []
    n = len(matrix)
    result = [[0]*n for _ in range(n)]
    for ring in range((n + 1) // 2):
        top = ring
        bottom = n - 1 - ring
        left = ring
        right = n - 1 - ring
        if top == bottom or left == right:
            for i in range(top, bottom + 1):
                result[i][left] = matrix[i][left]
            continue
        elements = []
        for i in range(top, bottom + 1):
            elements.append(matrix[i][right])
        for i in range(top + 1, bottom + 1):
            elements.append(matrix[bottom][i])
        for i in range(right - 1, left, -1):
            elements.append(matrix[i][left])
        for i in range(bottom - 1, top, -1):
            elements.append(matrix[top][i])
        k = k % len(elements)
        elements = elements[-k:] + elements[:-k]
        idx = 0
        for i in range(top, bottom + 1):
            result[i][right] = elements[idx]
            idx += 1
        for i in range(top + 1, bottom + 1):
            result[bottom][i] = elements[idx]
            idx += 1
