    import ast
    from ast import NodeTransformer, expr, Compare, operator, operators, and_, or_, not_

    class VariableReplacer(NodeTransformer):
        def visit_Name(self, node):
            if node.id in record:
                return ast.Name(id=node.id, ctx=ast.Load())
            else:
                raise ValueError(f"Unknown variable: {node.id}")

        def visit_Num(self, node):
            return node

        def visit_Str(self, node):
            return node

        def visit_BinOp(self, node):
            if isinstance(node.op, (operator.Lt, operator.LtE, operator.Gt, operator.GtE, operator.Eq, operator.NotEq)):
                return self.visit(node.left) and self.visit(node.right)
            elif isinstance(node.op, (and_, or_, not_)):
                return self.visit(node.left) and self.visit(node.right)
            else:
                raise ValueError(f"Unsupported operator: {type(node.op)}")

        def visit_Compare(self, node):
            left = self.visit(node.left)
            comparators = [self.visit(comp) for comp in node.comparators]
