def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine column widths
    col_widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    # Format each row
    formatted_rows = []
    for i, row in enumerate(rows):
        row_parts = []
        for j, cell in enumerate(row):
            width = col_widths[j]
            align = aligns[j]
            padding = width - len(cell)
            if align == 'l':
                row_parts.append(cell + ' ' * padding)
            elif align == 'r':
                row_parts.append(' ' * padding + cell)
            elif align == 'c':
                left_pad = padding // 2
                right_pad = padding - left_pad
                row_parts.append(' ' * left_pad + cell + ' ' * right_pad)
        formatted_rows.append(' | '.join(row_parts))

    return '\n'.join(formatted_rows)
