def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine column widths
    col_widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    # Format each cell based on alignment
    def format_cell(text: str, width: int, align: str) -> str:
        padding = width - len(text)
        if align == 'l':
            return text + ' ' * padding
        elif align == 'r':
            return ' ' * padding + text
        elif align == 'c':
            left_pad = padding // 2
            right_pad = padding - left_pad
            return ' ' * left_pad + text + ' ' * right_pad

    # Format each row
    formatted_rows = []
    for row in rows:
        formatted_cells = [format_cell(row[i], col_widths[i], aligns[i]) for i in range(len(row))]
        formatted_row = ' | '.join(formatted_cells)
        formatted_rows.append(formatted_row)

    return '\n'.join(formatted_rows)
