import ast
import re

def matches_filter(expression: str, record: dict) -> bool:
    # Check if all variables in the expression are keys in the record
    variables = re.findall(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\b', expression)
    for var in variables:
        if var not in record:
            raise ValueError(f"Unknown variable: {var}")

    # Create a new namespace with the record's keys as variables
    namespace = {key: value for key, value in record.items()}

    # Parse the expression into an AST
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid expression syntax")

    # Replace variable names with their values in the AST
    class ReplaceVariables(ast.NodeTransformer):
        def visit_Name(self, node):
            if node.id in namespace:
                return ast.Name(id=node.id, ctx=ast.Load())
            return node

    tree = ReplaceVariables().visit(tree)

    # Evaluate the expression in a secure environment
    try:
        result = eval(compile(tree, filename="<ast>", mode='eval'), namespace)
    except (NameError, TypeError, ValueError, SyntaxError):
        raise ValueError("Invalid expression")

    return result
