import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Check for invalid characters: backslash, space, or control characters
    if re.search(r'[\\ \x00-\x1F\x7F]', url):
        return False

    # Split URL into components
    url_parts = url.split('://')
    if len(url_parts) != 2:
        return False

    scheme, rest = url_parts
    if scheme != 'https':
        return False

    # Split into host and path
    if '/' in rest:
        host_part, path = rest.split('/', 1)
    else:
        host_part = rest
        path = ''

    # Check for user:password@ or user@ in host_part
    if '@' in host_part:
        host_part = host_part.split('@', 1)[1]

    # Check for port
    if ':' in host_part:
        host, port = host_part.split(':', 1)
        if port != '443':
            return False
    else:
        host = host_part

    # Check host format
    if host == 'localhost' or host.endswith('.localhost'):
        return False

    # Check if host ends with a dot and remove it
    if host.endswith('.'):
        host = host[:-1]

    # Check if host is a valid DNS name
    if not re.fullmatch(r'([a-zA-Z0-9-]+\.)*[a-zA-Z0-9-]+', host):
        return False

    # Check if host has at least two labels
    if len(host.split('.')) < 2:
        return False

    # Check if last label is only letters
    last_label = host.split('.')[-1]
    if not last_label.isalpha():
        return False

    # Check if all labels are valid
    for label in host.split('.'):
        if not label:
            return False
        if not re.fullmatch(r'[a-zA-Z0-9-]+', label):
            return False

    return True
