    # Check if URL starts with https:// (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Check for invalid characters: backslash, space, or control characters
    if re.search(r'[\\ \x00-\x1F\x7F]', url):
        return False

    # Split URL into components
    url_parts = url.split('@')
    if len(url_parts) > 2:
        return False  # Invalid format with user:password@ or user@

    # Split into scheme, host, port
    if '://' not in url:
        return False

    scheme, rest = url.split('://', 1)
    if scheme != 'https':
        return False

    if '@' in rest:
        host_port, _ = rest.split('@', 1)
    else:
        host_port = rest

    # Split host and port
    if ':' in host_port:
        host, port = host_port.split(':', 1)
    else:
        host = host_port
        port = None

    # Check port
    if port is not None:
        if port != '443':
            return False

    # Check host
    # Remove trailing dot if present
    if host.endswith('.'):
        host = host[:-1]

    # Check if host is 'localhost' or ends with '.localhost'
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    # Check host format: DNS name with labels
    if not re.fullmatch(r'([a-zA-Z0-9-]+\.)*[a-zA-Z0-9-]+', host):
