def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    col_widths = [max(len(cell) for cell in col) for col in zip(*rows)]
    num_cols = len(col_widths)

    def format_cell(cell: str, align: str, width: int) -> str:
        pad = width - len(cell)
        if pad == 0:
            return cell
        if align == 'l':
            return cell + ' ' * pad
        elif align == 'r':
            return ' ' * pad + cell
        else:  # 'c'
            pad_left = pad // 2
            pad_right = pad - pad_left
            return ' ' * pad_left + cell + ' ' * pad_right

    formatted_rows = []
    for i, row in enumerate(rows):
        if i == 0:
            formatted_rows.append(' | '.join(format_cell(cell, aligns[j], col_widths[j]) for j, cell in enumerate(row)))
        else:
            formatted_rows.append(' | '.join(format_cell(cell, aligns[j], col_widths[j]) for j, cell in enumerate(row)))

    return '\n'.join(formatted_rows)
