            return cell + ' ' * pad
        elif align == 'r':
            return ' ' * pad + cell
        else:  # 'c'
            if pad % 2 == 0:
                left_pad = pad // 2
                right_pad = left_pad
            else:
                left_pad = pad // 2 + 1
                right_pad = pad // 2
            return ' ' * left_pad + cell + ' ' * right_pad

    formatted_rows = []
    for i, row in enumerate(rows):
        if i == 0:
            formatted_rows.append(' | '.join(format_cell(cell, aligns[j], col_widths[j]) for j, cell in enumerate(row)))
        else:
            formatted_rows.append(' | '.join(format_cell(cell, aligns[j], col_widths[j]) for j, cell in enumerate(row)))

    return '\n'.join(formatted_rows)

