import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Check for invalid characters
    if re.search(r'[\\ \x00-\x1f\x7f]', url):
        return False

    # Split URL into components
    url_parts = url.split('://')
    if len(url_parts) != 2:
        return False

    scheme, rest = url_parts
    if scheme != 'https':
        return False

    # Split into host and path
    if '/' in rest:
        host_part, path = rest.split('/', 1)
    else:
        host_part = rest
        path = ''

    # Extract host and port
    if '@' in host_part:
        auth_part, host_part = host_part.split('@', 1)
    if ':' in host_part:
        host, port = host_part.split(':', 1)
    else:
        host = host_part
        port = None

    # Check port
    if port is not None:
        try:
            port = int(port)
        except ValueError:
            return False
        if port != 443:
            return False

    # Check host
    if host == 'localhost' or host.lower().endswith('.localhost'):
        return False

    # Check if host is a valid DNS name
    if not re.fullmatch(r'([a-zA-Z0-9-]+\.)*[a-zA-Z0-9-]+', host):
        return False

    return True
