from collections import defaultdict
import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    dist = {node: float('inf') for node in set(u for u, _, _ in edges)}
    dist[start] = 0
    prev = {node: None for node in set(u for u, _, _ in edges)}

    heap = [(0, start)]

    while heap:
        current_dist, u = heapq.heappop(heap)
        if u == goal:
            break
        if current_dist > dist[u]:
            continue
        for v, weight in graph[u]:
            if dist[v] > dist[u] + weight:
                dist[v] = dist[u] + weight
                prev[v] = u
                heapq.heappush(heap, (dist[v], v))
            elif dist[v] == dist[u] + weight and prev[v] is None and prev[u] is not None:
                prev[v] = u

    if dist[goal] == float('inf'):
        return None

    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = prev[current]
    path.reverse()

    return (dist[goal], path)
