from collections import deque

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = {}
    access_order = deque()
    results = []
    keys = []

    for op in operations:
        if op[0] == "put":
            key, value = op[1], op[2]
            if key in cache:
                # Update value and move to most recently used
                cache[key] = value
                access_order.remove(key)
            else:
                if len(cache) >= capacity:
                    # Remove least recently used
                    lru_key = access_order.popleft()
                    del cache[lru_key]
                # Add new key
            access_order.append(key)
            cache[key] = value
        elif op[0] == "get":
            key = op[1]
            if key in cache:
                # Move to most recently used
                access_order.remove(key)
                access_order.append(key)
                results.append(cache[key])
            else:
                results.append(None)

    # Convert deque to list in order from LRU to MRU
    keys = list(access_order)
    return (results, keys)
