def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = {}
    order = []
    results = []
    keys = []

    for op in operations:
        if op[0] == "put":
            key, value = op[1], op[2]
            if key in cache:
                # Update existing key and move to most recently used
                cache[key] = value
                order.remove(key)
            else:
                # Add new key
                if len(order) >= capacity:
                    # Remove least recently used
                    lru_key = order.pop(0)
                    del cache[lru_key]
                # Add new key to most recently used
            order.append(key)
            cache[key] = value
        elif op[0] == "get":
            key = op[1]
            if key in cache:
                # Move to most recently used
                order.remove(key)
                order.append(key)
                results.append(cache[key])
            else:
                results.append(None)

    # Prepare keys list from least recently used to most recently used
    keys = order[:]
    return (results, keys)
