import math
import re
import ast

def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the actual value
    formula = formula.replace('x', str(x))

    # Define a custom function for the math functions
    def math_func(name):
        if name == 'sqrt':
            return math.sqrt
        elif name == 'abs':
            return abs
        elif name == 'sin':
            return math.sin
        elif name == 'cos':
            return math.cos
        else:
            raise ValueError(f"Unknown function: {name}")

    # Replace function calls with lambda expressions
    formula = re.sub(r'(\w+)\(([^)]+)\)', lambda m: f'lambda {m.group(2)}: {math_func(m.group(1))}({m.group(2)})', formula)

    # Parse the formula using AST to ensure safety
    try:
        node = ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid formula syntax")

    # Check for invalid variable names
    for node in ast.walk(node):
        if isinstance(node, ast.Name) and node.id not in {'x', 'sqrt', 'abs', 'sin', 'cos'}:
            raise ValueError("Invalid variable name in formula")

    # Evaluate the formula safely
    try:
        result = eval(compile(node, '<string>', 'eval'), {'math': math, 'x': x})
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except Exception as e:
        raise ValueError("Invalid formula") from e

    return float(result)
