    # Replace 'x' with the actual value
    formula = formula.replace('x', str(x))

    # Define a custom function for safe evaluation
    def safe_eval(node):
        if isinstance(node, ast.Expression):
            return safe_eval(node.body)
        elif isinstance(node, ast.BinOp):
            left = safe_eval(node.left)
            right = safe_eval(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left / right
            elif isinstance(node.op, ast.Pow):
                return left ** right
            else:
                raise ValueError("Unsupported operator")
        elif isinstance(node, ast.UnaryOp):
            operand = safe_eval(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            else:
                raise ValueError("Unsupported unary operator")
        elif isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Name):
                func_name = func.id
                if func_name == 'sqrt':
                    if len(node.args) != 1:
                        raise ValueError("sqrt requires exactly one argument")
                    arg = safe_eval(node.args[0])
                    if arg < 0:
                        raise ValueError("Negative argument to sqrt")
                    return math.sqrt(arg)
                elif func_name == 'abs':
                    if len(node.args) != 1:
                        raise ValueError("abs requires exactly one argument")
                    return abs(safe_eval(node.args[0]))
                elif func_name == 'sin':
                    if len(node.args) != 1:
                        raise ValueError("sin requires exactly one argument")
                    return math.sin(safe_eval(node.args[0]))
                elif func_name == 'cos':
                    if len(node.args) != 1:
                        raise ValueError("cos requires exactly one argument")
                    return math.cos(safe_eval(node.args[0]))
                else:
                    raise ValueError(f"Unknown function: {func_name}")
            else:
                raise ValueError("Invalid function call")
        elif isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Name):
            if node.id == 'x':
                return x
            else:
                raise ValueError(f"Unknown variable: {node.id}")
        elif isinstance(node, ast.Compare):
            left = safe_eval(node.left)
            for op, right in zip(node.ops, node.comparators):
                right_val = safe_eval(right)
                if isinstance(op, ast.Gt):
                    if not (left > right_val):
                        raise ValueError("Comparison failed")
                elif isinstance(op, ast.Lt):
                    if not (left < right_val):
                        raise ValueError("Comparison failed")
                elif isinstance(op, ast.Eq):
                    if not (left == right_val):
                        raise ValueError("Comparison failed")
                else:
                    raise ValueError("Unsupported comparison operator")
            return left
        else:
            raise ValueError("Unsupported node type")

    # Parse the formula into an AST
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid formula syntax")

    # Check for invalid names
    if any(isinstance(n, ast.Name) and n.id not in {'x', 'sqrt', 'abs', 'sin', 'cos'} for n in ast.walk(tree)):
        raise ValueError("Formula contains invalid variable or function name")

