from jinja2 import Template, TemplateNotFound
import re

def render_mail_merge(template: str, recipients: list[dict]) -> list[str]:
    if not recipients:
        return []

    # Extract placeholders from the template
    placeholders = set()
    placeholder_pattern = re.compile(r'{{\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*}}')
    for match in placeholder_pattern.finditer(template):
        placeholders.add(match.group(1))

    # Render each recipient's template
    result = []
    for recipient in recipients:
        rendered = template
        for placeholder in placeholders:
            value = recipient.get(placeholder)
            if value is not None:
                rendered = rendered.replace(f'{{{{ {placeholder} }}}}', str(value))
            else:
                rendered = rendered.replace(f'{{{{ {placeholder} }}}}', '')
        result.append(rendered)

    return result

