def is_public_ip(ip_str: str) -> bool:
    try:
        # Check if the input is a valid IPv4 or IPv6 address
        ip = ipaddress.ip_address(ip_str)

        # Check if the IP is a private IP, loopback, link-local, multicast, or documentation address
        if ip.is_private:
            return False
        if ip.is_loopback:
            return False
        if ip.is_link_local:
            return False
        if ip.is_multicast:
            return False
        if ip.is_documentation:
            return False

        # Check for reserved IPv4 addresses
        if isinstance(ip, ipaddress.IPv4Address):
            # Check if it's a broadcast address
            if ip == ipaddress.IPv4Address('255.255.255.255'):
                return False
            # Check if it's in the shared address space (100.64.0.0/10)
            if ip in ipaddress.IPv4Network('100.64.0.0/10'):
                return False

        # Check for IPv4-mapped IPv6 addresses
        if isinstance(ip, ipaddress.IPv6Address) and ip.ipv4_mapped:
            # Check if the mapped IPv4 address is public
            mapped_ip = ip.ipv4_mapped
            if mapped_ip.is_private or mapped_ip.is_loopback or mapped_ip.is_link_local or mapped_ip.is_multicast or mapped_ip.is_documentation:
