def is_public_ip(ip_str: str) -> bool:
    try:
        # Check if the input is a valid IPv4 or IPv6 address
        ip = ipaddress.ip_address(ip_str)

        # Check if the IP is a private, loopback, link-local, multicast, or documentation address
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_documentation:
            return False

        # Check if the IP is in the shared address space (100.64.0.0/10)
        if isinstance(ip, ipaddress.IPv4Address):
            if ip.network_address <= ipaddress.IPv4Network('100.64.0.0/10').network_address <= ip:
                return False

        # Check if the IP is a broadcast address
        if isinstance(ip, ipaddress.IPv4Address) and ip == ipaddress.IPv4Network('255.255.255.255/32').network_address:
            return False

        # Check if the IP is an IPv4-mapped IPv6 address
        if isinstance(ip, ipaddress.IPv6Address) and ip.ipv4_mapped:
            return is_public_ip(str(ip.ipv4_mapped))

        return True
    except ValueError:
        return False

