import re
import urllib.parse

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Check for invalid characters: backslash, space, or control characters
    if re.search(r'[\\ \x00-\x1F\x7F]', url):
        return False

    # Parse URL
    parsed = urllib.parse.urlparse(url)
    if not parsed.scheme or not parsed.netloc:
        return False

    # Extract host (without user:password@ and port)
    host_part = parsed.netloc
    if '@' in host_part:
        host_part = host_part.split('@', 1)[1]
    if ':' in host_part:
        host_part = host_part.split(':', 1)[0]

    # Check if host is localhost or ends with .localhost
    if host_part.lower() == 'localhost' or host_part.lower().endswith('.localhost'):
        return False

    # Check if host is a valid DNS name
    if not re.fullmatch(r'([a-zA-Z0-9-]+\.)*[a-zA-Z0-9-]+', host_part):
        return False

    # Check if port is missing or is 443
    if parsed.port and parsed.port != 443:
        return False

    return True

