import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    while i < len(source):
        if source[i].isspace():
            i += 1
            continue
        if re.match(r'[0-9]', source[i]):
            # NUMBER
            j = i
            while j < len(source) and (source[j].isdigit() or source[j] == '.'):
                if source[j] == '.' and j + 1 < len(source) and source[j + 1].isdigit():
                    j += 1
                else:
                    break
            if j > i:
                if '.' in source[i:j] and source[i:j].count('.') > 1:
                    raise ValueError("Invalid number format")
                tokens.append(('NUMBER', source[i:j]))
                i = j
            else:
                raise ValueError("Invalid number format")
        elif re.match(r'[a-zA-Z_]', source[i]):
            # NAME
            j = i
            while j < len(source) and (source[j].isalnum() or source[j] == '_'):
                j += 1
            tokens.append(('NAME', source[i:j]))
            i = j
        else:
            # Check for two-character operators
            if i + 1 < len(source):
                op = source[i:i+2]
                if op in ('==', '!=', '<=', '>='):
                    tokens.append(('OP', op))
                    i += 2
                    continue
            # Check for single-character operators
            if source[i] in ('+', '-', '*', '/', '<', '>', '=', '(', ')', ','):
                tokens.append(('OP', source[i]))
                i += 1
            else:
                raise ValueError(f"Invalid character: {source[i]}")
    return tokens
