import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    # Define the regex pattern for the token types
    pattern = r'==|!=|<=|>=|[\+\-\*\/\<\>\=()]|,|\d+\.\d+|\d+|[a-zA-Z_][a-zA-Z0-9_]*'

    # Find all matches in the source code
    tokens = re.findall(pattern, source)

    # Check for invalid characters
    for token in tokens:
        if not re.fullmatch(r'==|!=|<=|>=|[\+\-\*\/\<\>\=()]|,|\d+\.\d+|\d+|[a-zA-Z_][a-zA-Z0-9_]*', token):
            raise ValueError(f"Invalid character in source: {token}")

    # Classify each token
    result = []
    i = 0
    while i < len(source):
        if source[i].isspace():
            i += 1
            continue
        if source[i:i+2] in ('==', '!=', '<=', '>='):
            result.append(('OP', source[i:i+2]))
            i += 2
        elif source[i] in '+-*/<>=(),':
            result.append(('OP', source[i]))
            i += 1
        elif re.match(r'\d', source[i]):
            # Match the longest possible number
            j = i
            while j < len(source) and (source[j].isdigit() or (source[j] == '.' and source[j+1].isdigit() if j+1 < len(source) else False)):
                j += 1
            if j - i > 0:
                num = source[i:j]
                if '.' in num:
                    result.append(('NUMBER', num))
                else:
                    result.append(('NUMBER', num))
                i = j
        elif re.match(r'[a-zA-Z_]', source[i]):
            # Match the longest possible name
            j = i
            while j < len(source) and (source[j].isalnum() or source[j] == '_'):
                j += 1
            result.append(('NAME', source[i:j]))
            i = j
        else:
            raise ValueError(f"Invalid character in source: {source[i]}")

    return result
