def evaluate_expression(expr: str) -> int:
    import re
    from collections import deque

    expr = re.sub(r'\s+', '', expr)
    tokens = re.findall(r'(\d+|\+|\-|\*|/|\^|\(|\))', expr)

    def parse_expression(tokens):
        tokens = deque(tokens)
        def parse_term():
            if tokens[0] == '(':
                tokens.popleft()
                result = parse_expression(tokens)
                if tokens[0] != ')':
                    raise ValueError("Mismatched parentheses")
                tokens.popleft()
                return result
            elif tokens[0] == '-':
                tokens.popleft()
                return -parse_term()
            else:
                return int(tokens.popleft())

        def parse_factor():
            left = parse_term()
            while tokens and tokens[0] == '^':
                tokens.popleft()
                right = parse_factor()
                left = left ** right
            return left

        def parse_product():
            left = parse_factor()
            while tokens and tokens[0] in ('*', '/'):
                op = tokens.popleft()
                right = parse_factor()
                if op == '*':
                    left *= right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    left = left // right if left >= 0 else -(abs(left) // right)
            return left

        def parse_sum():
            left = parse_product()
            while tokens and tokens[0] in ('+', '-'):
                op = tokens.popleft()
                right = parse_product()
                if op == '+':
                    left += right
                else:
                    left -= right
            return left

        return parse_sum()

    return parse_expression(tokens)
