def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine the maximum width for each column
    col_widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    # Format each cell based on alignment
    def format_cell(text: str, align: str, width: int) -> str:
        if align == 'l':
            return text.ljust(width)
        elif align == 'r':
            return text.rjust(width)
        elif align == 'c':
            return text.center(width)

    # Format each row
    formatted_rows = []
    for row in rows:
        formatted_cells = [format_cell(row[i], aligns[i], col_widths[i]) for i in range(len(row))]
        formatted_row = " | ".join(formatted_cells)
        formatted_rows.append(formatted_row)

    return "\n".join(formatted_rows)
