from jinja2 import Template

def render_mail_merge(template: str, recipients: list[dict]) -> list[str]:
    if not recipients:
        return []

    template_obj = Template(template)
    result = []

    for recipient in recipients:
        try:
            rendered = template_obj.render(recipient)
            result.append(rendered)
        except Exception as e:
            # In case of any rendering error, append empty string as a safe fallback
            result.append("")

    return result
