    if not matrix:
        return []
    n = len(matrix)
    result = [[0]*n for _ in range(n)]
    for ring in range((n + 1) // 2):
        top = ring
        bottom = n - 1 - ring
        left = ring
        right = n - 1 - ring
        if top == bottom or left == right:
            for i in range(top, bottom + 1):
                result[i][left] = matrix[i][left]
            continue
        size = (bottom - top + 1) * 4 - 4
        k = k % size
        if k < 0:
            k += size
        # Save the top row
        temp = [matrix[i][left] for i in range(top, bottom + 1)]
        # Rotate the right column
        for i in range(top, bottom + 1):
            result[i][right] = matrix[i + 1][right] if i + 1 <= bottom else matrix[top][right]
        # Rotate the bottom row
        for i in range(right, left - 1, -1):
            result[bottom][i] = matrix[bottom][i + 1] if i + 1 <= right else matrix[bottom][left]
        # Rotate the left column
        for i in range(bottom, top, -1):
            result[i][left] = matrix[i - 1][left] if i - 1 >= top else matrix[bottom][left]
        # Fill the top row with the rotated values
        for i in range(k):
            result[top][left + i] = temp[i]
    return result

