def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = {}
    usage_order = []
    results = []
    keys = []

    def move_to_recent(key):
        if key in usage_order:
            usage_order.remove(key)
        usage_order.append(key)

    for op in operations:
        if op[0] == "put":
            key, value = op[1], op[2]
            if key in cache:
                cache[key] = value
                move_to_recent(key)
            else:
                if len(cache) >= capacity and capacity > 0:
                    lru_key = usage_order.pop(0)
                    del cache[lru_key]
                cache[key] = value
                move_to_recent(key)
        elif op[0] == "get":
            key = op[1]
            if key in cache:
                results.append(cache[key])
                move_to_recent(key)
            else:
                results.append(None)

    keys = usage_order.copy()
    return (results, keys)
