import ipaddress

def is_public_ip(ip_str: str) -> bool:
    try:
        # Try to parse as IPv4
        ip = ipaddress.IPv4Address(ip_str)
        # Check if it's a public IPv4 address
        return not ip.is_private and not ip.is_loopback and not ip.is_link_local and not ip.is_multicast and not ip.is_reserved and not ip.is_documentation and not ip.is_unspecified and not (ip.network_address == ip.broadcast_address)
    except ValueError:
        try:
            # Try to parse as IPv6
            ip = ipaddress.IPv6Address(ip_str)
            # Check if it's a public IPv6 address
            return not ip.is_private and not ip.is_loopback and not ip.is_link_local and not ip.is_multicast and not ip.is_reserved and not ip.is_documentation and not ip.is_unspecified
        except ValueError:
            # Check if it's an IPv4-mapped IPv6 address
            if ip_str.startswith('::ffff:'):
                ipv4_part = ip_str[7:]
                if '.' in ipv4_part:
                    try:
                        ipv4_ip = ipaddress.IPv4Address(ipv4_part)
                        return not ipv4_ip.is_private and not ipv4_ip.is_loopback and not ipv4_ip.is_link_local and not ipv4_ip.is_multicast and not ipv4_ip.is_reserved and not ipv4_ip.is_documentation and not ipv4_ip.is_unspecified and not (ipv4_ip.network_address == ipv4_ip.broadcast_address)
                    except ValueError:
                        return False
            return False
    except ipaddress.AddressValueError:
        return False
