def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = {}
    order = []
    results = []

    for op in operations:
        if op[0] == "put":
            key, value = op[1], op[2]
            if key in cache:
                cache[key] = value
                order.remove(key)
            else:
                if len(cache) >= capacity:
                    lru_key = order.pop(0)
                    del cache[lru_key]
                order.append(key)
                cache[key] = value
        elif op[0] == "get":
            key = op[1]
            if key in cache:
                order.remove(key)
                order.append(key)
                results.append(cache[key])
            else:
                results.append(None)

    return (results, order)
