import re
from urllib.parse import urlparse

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Check for invalid characters: backslash, space, control characters
    if '\\' in url or ' ' in url or any(ord(c) < 32 or ord(c) == 127 for c in url):
        return False

    # Parse URL
    parsed = urlparse(url)
    if parsed.scheme != 'https':
        return False

    # Extract host
    host = parsed.hostname
    if not host:
        return False

    # Check for localhost or .localhost
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    # Remove trailing dot if present
    if host.endswith('.'):
        host = host[:-1]

    # Check if host is a valid FSN
    # Split host into labels
    labels = host.split('.')
    if len(labels) < 2:
        return False

    # Check each label
    for label in labels:
        if not label:
            return False
        if not re.fullmatch(r'[a-zA-Z0-9-]+', label):
            return False

    # Check last label is only letters
    if not re.fullmatch(r'[a-zA-Z]+', labels[-1]):
        return False

    # Check port
    if parsed.port and parsed.port != 443:
        return False

    return True
