def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0
    instructions = {
        'PUSH': lambda x: stack.append(int(x)),
        'POP': lambda: stack.pop() if stack else None,
        'DUP': lambda: stack.append(stack[-1]) if stack else None,
        'SWAP': lambda: (stack[-1], stack[-2]) if len(stack) >= 2 else None,
        'ADD': lambda: stack.append(stack.pop() + stack.pop()) if len(stack) >= 2 else None,
        'SUB': lambda: stack.append(stack.pop() - stack.pop()) if len(stack) >= 2 else None,
        'MUL': lambda: stack.append(stack.pop() * stack.pop()) if len(stack) >= 2 else None,
        'JMP': lambda t: (pc := int(t)) if int(t) >= 0 and int(t) < len(program) else None,
        'JZ': lambda t: (pc := int(t)) if stack and stack[-1] == 0 else None,
        'HALT': lambda: None
    }

    executed_instructions = 0
    while executed_instructions < 1000:
        if pc >= len(program):
            break
        instr = program[pc]
        parts = instr.split()
        if parts[0] not in instructions:
            raise ValueError(f"Unknown instruction: {instr}")
        if parts[0] in ['JMP', 'JZ']:
            if len(parts) < 2:
                raise ValueError(f"Invalid instruction: {instr}")
            instructions[parts[0]](parts[1])
        else:
            instructions[parts[0]]()
        executed_instructions += 1
        pc += 1

    if executed_instructions >= 1000:
        raise RuntimeError("Too many instructions executed")

    return list(reversed(stack))
