import re
import urllib.parse

def is_allowed_webhook(url: str) -> bool:
    if not url.startswith('https://'):
        return False

    try:
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme != 'https':
            return False

        host = parsed.netloc
        if not host:
            return False

        if host == 'localhost' or host.endswith('.localhost'):
            return False

        if ':' in host:
            host, port = host.split(':', 1)
            if port != '443':
                return False

        if not re.fullmatch(r'([a-zA-Z0-9-]+\.)*[a-zA-Z0-9-]+', host):
            return False

        if any(c in r' \t\n\r\f\v' for c in host):
            return False

        if not re.fullmatch(r'^https://[a-zA-Z0-9-]+(\.[a-zA-Z0-9-]+)*(:[0-9]+)?$', url):
            return False

        return True
    except:
        return False
