import re
import operator

def evaluate_expression(expr: str) -> int:
    expr = re.sub(r'\s+', '', expr)

    def parse_expression(tokens):
        def parse_power(tokens):
            left = parse_unary(tokens)
            while tokens and tokens[0] == '^':
                tokens.pop(0)
                right = parse_power(tokens)
                left = operator.pow(left, right)
            return left

        def parse_unary(tokens):
            if tokens and tokens[0] == '-':
                tokens.pop(0)
                return -parse_power(tokens)
            return parse_multiplicative(tokens)

        def parse_multiplicative(tokens):
            left = parse_additive(tokens)
            while tokens and tokens[0] in ('*', '/'):
                op = tokens.pop(0)
                right = parse_additive(tokens)
                if op == '*':
                    left *= right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    left = left // right
            return left

        def parse_additive(tokens):
            left = parse_primary(tokens)
            while tokens and tokens[0] in ('+', '-'):
                op = tokens.pop(0)
                right = parse_primary(tokens)
                if op == '+':
                    left += right
                else:
                    left -= right
            return left

        def parse_primary(tokens):
            if tokens[0] == '(':
                tokens.pop(0)
                result = parse_expression(tokens)
                if tokens[0] != ')':
                    raise ValueError("unmatched parenthesis")
                tokens.pop(0)
                return result
            else:
                return int(tokens.pop(0))

        return parse_expression(tokens)

    tokens = re.findall(r'(\d+|\+|\-|\*|/|\^|\(|\))', expr)
    return parse_expression(tokens)
