def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    order_sequence = []

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] = stock.get(item, 0) + quantity
            # Fulfill waiting orders in sequence
            while waiting and stock[item] >= waiting[0][1]:
                order_item, order_qty = waiting.pop(0)
                order_sequence.append((order_item, order_qty))
                stock[item] -= order_qty
        elif kind == 'order':
            waiting.append((item, quantity))

    # Prepare the final waiting list in order of occurrence
    waiting.sort(key=lambda x: order_sequence.index(x) if x in order_sequence else float('inf'))
    return stock, waiting
