def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0  # instruction pointer
    max_instructions = 1000
    executed_instructions = 0

    while executed_instructions < max_instructions:
        if ip >= len(program):
            break
        instr = program[ip]
        executed_instructions += 1

        if instr.startswith("PUSH "):
            _, n = instr.split()
            stack.append(int(n))
            ip += 1
        elif instr == "POP":
            if not stack:
                return None
            stack.pop()
            ip += 1
        elif instr == "DUP":
            if not stack:
                return None
            stack.append(stack[-1])
            ip += 1
        elif instr == "SWAP":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1
        elif instr.startswith("ADD"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
            ip += 1
        elif instr.startswith("SUB"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            ip += 1
        elif instr.startswith("MUL"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
            ip += 1
        elif instr.startswith("JMP "):
            _, t = instr.split()
            ip = int(t)
        elif instr.startswith("JZ "):
            _, t = instr.split()
            if stack and stack[-1] == 0:
                ip = int(t)
            else:
                ip += 1
        else:
            return None

    if executed_instructions >= max_instructions:
        return None

    return list(reversed(stack))
