    ip = 0  # instruction pointer
    max_instructions = 1000
    executed_instructions = 0

    while executed_instructions < max_instructions:
        if ip >= len(program):
            break
        instruction = program[ip]
        executed_instructions += 1

        if instruction.startswith("PUSH "):
            _, n = instruction.split()
            stack.append(int(n))
            ip += 1
        elif instruction == "POP":
            if not stack:
                return None
            stack.pop()
            ip += 1
        elif instruction == "DUP":
            if not stack:
                return None
            stack.append(stack[-1])
            ip += 1
        elif instruction == "SWAP":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1
        elif instruction.startswith("ADD"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
            ip += 1
        elif instruction.startswith("SUB"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            ip += 1
        elif instruction.startswith("MUL"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
            ip += 1
        elif instruction.startswith("JMP "):
            _, t = instruction.split()
            ip = int(t)
        elif instruction.startswith("JZ "):
            _, t = instruction.split()
            if stack and stack[-1] == 0:
                ip = int(t)
            else:
                ip += 1
        else:
            return None

    if executed_instructions >= max_instructions:
        return None

    return list(reversed(stack))
