def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    order_sequence = []

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] = stock.get(item, 0) + quantity
            # Process waiting orders in sequence
            while waiting:
                waiting_item, waiting_qty = waiting[0]
                if stock.get(waiting_item, 0) >= waiting_qty:
                    # Fulfill the order
                    stock[waiting_item] -= waiting_qty
                    waiting.pop(0)
                    order_sequence.append((waiting_item, waiting_qty))
                else:
                    break
        elif kind == 'order':
            waiting.append((item, quantity))

    # Sort waiting orders by the order they were added
    waiting.sort(key=lambda x: order_sequence.index(x) if x in order_sequence else float('inf'))
    return stock, waiting
