    stack = []
    ip = 0
    instructions_executed = 0
    while ip < len(program) and instructions_executed < 1000:
        instructions_executed += 1
        instr = program[ip]
        if instr.startswith('PUSH '):
            _, n = instr.split()
            stack.append(int(n))
