            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instr.startswith('ADD'):
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
        elif instr.startswith('SUB'):
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
        elif instr.startswith('MUL'):
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
        elif instr.startswith('JMP '):
            _, t = instr.split()
            ip = int(t)
        elif instr.startswith('JZ '):
            _, t = instr.split()
            if stack and stack[-1] == 0:
                ip = int(t)
            else:
                ip += 1
        else:
            ip += 1
    if instructions_executed >= 1000:
        return None
    return stack
