def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []

    for kind, item, quantity in events:
        if kind == 'receive':
            if item not in stock:
                stock[item] = 0
            stock[item] += quantity
            # Process waiting orders
            while waiting and stock[item] > 0:
                waiting_item, waiting_quantity = waiting[0]
                if waiting_item == item:
                    if stock[item] >= waiting_quantity:
                        stock[item] -= waiting_quantity
                        waiting.pop(0)
                    else:
                        break
                else:
                    break
        elif kind == 'order':
            if item not in stock:
                stock[item] = 0
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))

    # Remove items with zero stock from the dictionary
    stock = {item: qty for item, qty in stock.items() if qty > 0}

    return stock, waiting
