def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = {}
    for event in events:
        kind, item, quantity = event
        if kind == 'receive':
            if item not in stock:
                stock[item] = 0
            stock[item] += quantity
            # Process waiting orders for this item
            while item in waiting and stock[item] >= waiting[item][1]:
                order_item, order_qty = waiting[item].pop(0)
                stock[order_item] -= order_qty
        else:  # 'order'
            if item not in stock:
                stock[item] = 0
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                if item not in waiting:
                    waiting[item] = []
                waiting[item].append((item, quantity))
    # Prepare the final waiting list in order of placement
    waiting_list = []
    for item in waiting:
        waiting_list.extend(waiting[item])
    # Include items with zero stock in the stock dictionary
    for item in waiting:
        if item not in stock:
            stock[item] = 0
    return (stock, waiting_list)
