def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    executed = 0
    while ip < len(program) and executed < 1000:
        executed += 1
        instr = program[ip]
        if instr.startswith('PUSH '):
            _, n = instr.split()
            stack.append(int(n))
        elif instr == 'POP':
            if stack:
                stack.pop()
        elif instr == 'DUP':
            if stack:
                stack.append(stack[-1])
        elif instr == 'SWAP':
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instr.startswith('ADD'):
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
        elif instr.startswith('SUB'):
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
        elif instr.startswith('MUL'):
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
        elif instr.startswith('JMP '):
            _, t = instr.split()
            ip = int(t)
        elif instr.startswith('JZ '):
            _, t = instr.split()
            if stack:
                val = stack.pop()
                if val == 0:
                    ip = int(t)
                else:
                    ip += 1
            else:
                ip += 1
        else:
            ip += 1
    if executed >= 1000:
        return None
    return stack
