def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0
    instruction_count = 0
    while pc < len(program) and instruction_count < 1000:
        instruction = program[pc]
        instruction_count += 1
        if instruction.startswith("PUSH "):
            try:
                n = int(instruction.split()[1])
                stack.append(n)
            except (ValueError, IndexError):
                raise ValueError("Invalid PUSH instruction")
        elif instruction == "POP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif instruction == "DUP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif instruction == "SWAP":
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction.startswith("ADD") or instruction.startswith("SUB") or instruction.startswith("MUL"):
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            a, b = stack.pop(), stack.pop()
            if instruction == "ADD":
                stack.append(a + b)
            elif instruction == "SUB":
                stack.append(a - b)
            elif instruction == "MUL":
                stack.append(a * b)
        elif instruction.startswith("JMP "):
            try:
                t = int(instruction.split()[1])
                pc = t
            except (ValueError, IndexError):
                raise ValueError("Invalid JMP instruction")
        elif instruction.startswith("JZ "):
            try:
                t = int(instruction.split()[1])
                if stack and stack[-1] == 0:
                    pc = t
                else:
                    pc += 1
            except (ValueError, IndexError):
                raise ValueError("Invalid JZ instruction")
        elif instruction == "HALT":
            break
        else:
            raise ValueError("Unknown instruction")
        pc += 1
    if instruction_count >= 1000:
        raise RuntimeError("Too many instructions executed")
    return stack
