def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0
    instructions = {
        'PUSH': lambda x: stack.append(int(x.split()[1])),
        'POP': lambda: stack.pop() if stack else raise ValueError("Stack underflow"),
        'DUP': lambda: stack.append(stack[-1]) if stack else raise ValueError("Stack underflow"),
        'SWAP': lambda: (stack[-1], stack[-2]) if len(stack) >= 2 else raise ValueError("Stack underflow"),
        'ADD': lambda: (stack.pop(), stack.pop(), stack.append(stack.pop() + stack.pop())) if len(stack) >= 2 else raise ValueError("Stack underflow"),
        'SUB': lambda: (stack.pop(), stack.pop(), stack.append(stack.pop() - stack.pop())) if len(stack) >= 2 else raise ValueError("Stack underflow"),
        'MUL': lambda: (stack.pop(), stack.pop(), stack.append(stack.pop() * stack.pop())) if len(stack) >= 2 else raise ValueError("Stack underflow"),
        'JMP': lambda t: (pc := int(t)),
        'JZ': lambda t: (pc := int(t) if stack[-1] == 0 else pc + 1) if stack else raise ValueError("Stack underflow"),
        'HALT': lambda: None
    }
    for _ in range(1000):
        if pc >= len(program):
            break
        instr = program[pc]
        parts = instr.split()
        if parts[0] in instructions:
            try:
                instructions[parts[0]](parts[1] if len(parts) > 1 else None)
            except:
                raise ValueError("Invalid instruction")
            pc += 1
        else:
            raise ValueError("Invalid instruction")
    if len(stack) > 1000:
        raise RuntimeError("Too many instructions executed")
    return stack
