        elif instr.startswith("ADD") or instr.startswith("SUB") or instr.startswith("MUL"):
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                if instr == "ADD":
                    stack.append(a + b)
                elif instr == "SUB":
                    stack.append(a - b)
                elif instr == "MUL":
                    stack.append(a * b)
        elif instr.startswith("JMP "):
            _, t = instr.split()
            pc = int(t)
        elif instr.startswith("JZ "):
            _, t = instr.split()
            t = int(t)
            if stack and stack[-1] == 0:
                pc = t
            else:
                pc += 1
        else:
            pc += 1
    if pc >= len(program):
        return stack
    return None
