def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed = []
    frozen = set()

    for i, op in enumerate(ops):
        if op[0] not in {'deposit', 'withdraw', 'transfer', 'freeze', 'unfreeze'}:
            failed.append(i)
            continue

        if op[0] == 'deposit':
            account, amount = op[1], op[2]
            if account not in final_balances or amount <= 0 or account in frozen:
                failed.append(i)
                continue
            final_balances[account] += amount

        elif op[0] == 'withdraw':
            account, amount = op[1], op[2]
            if account not in final_balances or amount <= 0 or account in frozen or final_balances[account] < amount:
                failed.append(i)
                continue
            final_balances[account] -= amount

        elif op[0] == 'transfer':
            source, target, amount = op[1], op[2], op[3]
            if source == target or source not in final_balances or target not in final_balances or amount <= 0 or source in frozen or target in frozen or final_balances[source] < amount + 2:
                failed.append(i)
                continue
            final_balances[source] -= amount + 2
            final_balances[target] += amount

        elif op[0] == 'freeze':
            account = op[1]
            if account in final_balances and account not in frozen:
                frozen.add(account)

        elif op[0] == 'unfreeze':
            account = op[1]
            if account in final_balances and account in frozen:
                frozen.remove(account)

    return final_balances, sorted(failed)
