            else:
                waiting[item] = (waiting[item][0], waiting[item][1] + quantity)

    # Prepare the final waiting list
    waiting_list = []
    for item in sorted(waiting.keys()):
        waiting_list.append((item, waiting[item][1]))

    return stock, waiting_list
