                continue
            if account in frozen:
                failed.append(idx)
                continue
            final_balances[account] += amount
        elif op[0] == 'withdraw':
            account, amount = op[1], op[2]
            if account not in final_balances or amount <= 0:
                failed.append(idx)
                continue
            if account in frozen:
                failed.append(idx)
                continue
            if final_balances[account] - amount < 0:
                failed.append(idx)
                continue
            final_balances[account] -= amount
        elif op[0] == 'transfer':
            source, target, amount = op[1], op[2], op[3]
            if source == target:
                failed.append(idx)
                continue
            if source not in final_balances or target not in final_balances or amount <= 0:
                failed.append(idx)
                continue
            if source in frozen or target in frozen:
                failed.append(idx)
                continue
            if final_balances[source] - amount - 2 < 0:
                failed.append(idx)
                continue
            final_balances[source] -= amount + 2
            final_balances[target] += amount
        elif op[0] == 'freeze':
            account = op[1]
            if account not in final_balances:
                failed.append(idx)
                continue
            if account not in frozen:
                frozen.add(account)
        elif op[0] == 'unfreeze':
            account = op[1]
            if account not in final_balances:
                failed.append(idx)
                continue
            if account in frozen:
                frozen.remove(account)
        else:
            failed.append(idx)

    return final_balances, failed
