def top_k_elements(nums: list[int], k: int) -> list[int]:
    freq = defaultdict(int)
    for num in nums:
        freq[num] += 1

    ordered = OrderedDict()
    for num in nums:
        if freq[num] > 0:
            ordered[num] = freq[num]
            freq[num] = 0

    sorted_items = sorted(ordered.items(), key=lambda x: (-x[1], nums.index(x[0])))
    return [item[0] for item in sorted_items[:k]]

