def smallest_lcs(a: str, b: str) -> str:
    m, n = len(a), len(b)
    dp = [[(0, '') for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                current = (1 + dp[i + 1][j + 1][0], a[i] + dp[i + 1][j + 1][1])
            else:
                current = max(dp[i + 1][j], dp[i][j + 1])
            dp[i][j] = current

    return dp[0][0][1]
