from typing import List

def min_coins_bounded(coins: List[int], limits: List[int], target: int) -> int:
    if target == 0:
        return 0

    # Initialize a dynamic programming array where dp[i] represents the minimum coins needed to make amount i
    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    for i in range(1, target + 1):
        for coin_idx in range(len(coins)):
            coin = coins[coin_idx]
            limit = limits[coin_idx]
            if coin > i:
