def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    blocked_set = set((r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n)

    def is_safe(board, row, col):
        for r, c in board:
            if c == col or abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(queens):
        if len(queens) == n:
            return 1
        count = 0
        for col in range(n):
            row = len(queens)
            if (row, col) in blocked_set:
                continue
            if is_safe(queens, row, col):
                count += backtrack(queens + [(row, col)])
        return count

    return backtrack([])
