def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    grid = [row[:] for row in grid]

    while True:
        toppling = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] >= 4:
                    toppling = True
                    grid[r][c] -= 4
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            grid[nr][nc] += 1
        if not toppling:
            break

    return grid
