def is_valid_email(s: str) -> bool:
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')

    # Validate local part
    if not re.fullmatch(r'[a-zA-Z0-9](?:[a-zA-Z0-9._-]*[a-zA-Z0-9])', local):
        return False

    # Validate domain part
    if not re.fullmatch(r'[a-zA-Z0-9]+(\.[a-zA-Z0-9]+)+', domain):
        return False

    # Ensure the last label of the domain is all letters
    if not domain.endswith('.'.join([domain.split('.')[-1]])):
        return False

    return True

