def expand_template(template: str, values: dict[str, str]) -> str:
    result = []
    i = 0
    while i < len(template):
        if i + 1 < len(template) and template[i:i+2] == '{{':
            result.append('{')
            i += 2
        elif i + 1 < len(template) and template[i:i+2] == '}}':
            result.append('}')
            i += 2
        elif template[i] == '{':
            # Start of a placeholder
            start = i
            i += 1
            while i < len(template) and template[i] != '}':
                i += 1
            if i < len(template) and template[i] == '}':
                key = template[start+1:i]
                if key in values:
                    result.append(values[key])
                else:
                    result.append('{' + key + '}')
                i += 1
            else:
                # Invalid placeholder, treat '{' as regular character
                result.append('{')
                i += 1
        else:
            result.append(template[i])
            i += 1
    return ''.join(result)
