            return (a, 1, 0)
        else:
            g, x, y = extended_gcd(b, a % b)
            return (g, y, x - (a // b) * y)

    def crt(c1, m1, c2, m2):
        g, x, y = extended_gcd(m1, m2)
        if (c2 - c1) % g != 0:
            return None
        lcm = m1 // g * m2
        x = (c1 + (c2 - c1) // g * x * m1) % lcm
        return (x, lcm)

    x, m = congruences[0]
    for (r, mod) in congruences[1:]:
        result = crt(x, m, r, mod)
        if result is None:
            return None
        x, m = result

    return (x, m)

