        if deadline < 1:
            continue
        # Find the highest-numbered free slot <= deadline
        slot = None
        for s in range(deadline, 0, -1):
            if s not in slots:
                slot = s
                break
        if slot is not None:
            slots[slot] = name
            result.append((slot, name))

    # Sort the result by slot number
    result.sort()
    return [name for _, name in result]
