        if len(path) == len(guests):
            result.append(path.copy())
            return
        for guest in guests:
            if guest in used:
                continue
            valid = True
            for prev in path:
                if (prev, guest) in conflict_set or (guest, prev) in conflict_set:
                    valid = False
                    break
            if valid:
                path.append(guest)
                used.add(guest)
                backtrack(path, used)
                path.pop()
                used.remove(guest)

    backtrack([], set())
    result.sort()
    return result

