from collections import deque

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = {}
    order = deque()
    results = []
    keys = []

    for op in operations:
        if op[0] == "put":
            key, value = op[1], op[2]
            if key in cache:
                # Update existing key and move to front
                order.remove(key)
            else:
                # If cache is full, remove least recently used
                if len(order) >= capacity:
                    lru_key = order.popleft()
                    del cache[lru_key]
            # Add the key to the front
            order.append(key)
            cache[key] = value
        elif op[0] == "get":
            key = op[1]
            if key in cache:
                # Move to front
                order.remove(key)
                order.append(key)
                results.append(cache[key])
            else:
                results.append(None)

    # Convert order deque to list from LRU to MRU
    keys = list(order)
    return (results, keys)
