            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(pos):
        i, j = pos
        neighbors = []
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < rows and 0 <= nj < cols and grid[ni][nj] != '#':
                ni2, nj2 = ni, nj
                while 0 <= ni2 < rows and 0 <= nj2 < cols and grid[ni2][nj2] != '#':
                    ni2 += dx
                    nj2 += dy
                ni2 -= dx
                nj2 -= dy
                if (ni2, nj2) != (i, j):
