            key, value = op[1], op[2]
            if key in cache:
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
            cache[key] = value
        elif op[0] == "get":
            key = op[1]
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(None)

    keys = list(cache.keys())
    return (results, keys)
