import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    pq = [(0, start, [start])]
    visited = set()

    while pq:
        cost, node, path = heapq.heappop(pq)
        if node == goal:
            return (cost, path)
        if node in visited:
            continue
        visited.add(node)
        for neighbor, weight in graph.get(node, []):
            if neighbor not in visited:
                new_path = path + [neighbor]
                heapq.heappush(pq, (cost + weight, neighbor, new_path))

    return None
