import ipaddress

def is_public_ip(ip_str: str) -> bool:
    try:
        # Attempt to parse the IP string
        ip = ipaddress.ip_address(ip_str)
    except ValueError:
        return False

    # Check if the IP is IPv4
    if ip.version == 4:
        # Check if it's a private IP
        if ip.is_private:
            return False
        # Check if it's a loopback
        if ip.is_loopback:
            return False
        # Check if it's a link-local
        if ip.is_link_local:
            return False
        # Check if it's a multicast
        if ip.is_multicast:
            return False
        # Check if it's unspecified
        if ip.is_unspecified:
            return False
        # Check if it's a broadcast address
        if ip.is_broadcast:
            return False
        # Check if it's in the shared address space 100.64.0.0/10
        if ip.network_address in ipaddress.ip_network('100.64.0.0/10'):
            return False
        return True
    elif ip.version == 6:
        # Check if it's an IPv4-mapped IPv6 address
        if ip.ipv4_mapped:
            return is_public_ip(str(ip.ipv4_mapped))
        # Check if it's a private IPv6
        if ip.is_private:
            return False
        # Check if it's a loopback
        if ip.is_loopback:
            return False
        # Check if it's a link-local
        if ip.is_link_local:
            return False
        # Check if it's a multicast
        if ip.is_multicast:
            return False
        # Check if it's unspecified
        if ip.is_unspecified:
            return False
        return True
    return False
