from urllib.parse import urlparse

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Check for backslash, space, or control characters
    if re.search(r'[\s\\\x00-\x1f\x7f]', url):
        return False

    # Parse URL
    parsed = urlparse(url)
    if parsed.scheme != 'https':
        return False

    # Extract host
    host = parsed.hostname
    if not host:
        return False

    # Check if host ends with a dot
    if not host.endswith('.'):
        return False

    # Remove the final dot
    host_without_dot = host[:-1]

    # Check if host_without_dot is a valid DNS name
    # Split into labels
    labels = host_without_dot.split('.')
    if len(labels) < 2:
        return False

    # Check each label
    for i, label in enumerate(labels):
        if not label:
            return False
        if not re.fullmatch(r'[a-zA-Z0-9-]+', label):
            return False

    # Check last label must be only letters
    if not re.fullmatch(r'[a-zA-Z]+', labels[-1]):
        return False

    # Check host is not 'localhost' or ends with '.localhost'
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    # Check port is absent or 443
    if parsed.port is not None and parsed.port != 443:
        return False

    return True

