def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    order_index = 0

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            if item not in stock:
                stock[item] = 0
            stock[item] += quantity

            # Fulfill waiting orders for this item
            while waiting and waiting[0][0] == item:
                waiting_order = waiting.pop(0)
                if stock[item] >= waiting_order[1]:
                    stock[item] -= waiting_order[1]
                else:
                    waiting.insert(0, waiting_order)
                    break
        else:  # 'order'
            if item not in stock:
                stock[item] = 0
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))

    # Ensure all items in waiting are included in stock with 0 if not present
    for item, qty in waiting:
        if item not in stock:
            stock[item] = 0

    return (stock, waiting)
