            if final_balances[account] - amount < 0:
                failed.append(i)
                continue
            final_balances[account] -= amount

        elif op_type == 'transfer':
            source, target, amount = op[1], op[2], op[3]
            if source == target or source not in final_balances or target not in final_balances or amount <= 0 or source in frozen or target in frozen:
                failed.append(i)
                continue
            if final_balances[source] - amount - 2 < 0:
                failed.append(i)
                continue
            final_balances[source] -= amount + 2
            final_balances[target] += amount

        elif op_type == 'freeze':
            account = op[1]
            if account in final_balances and account not in frozen:
                frozen.add(account)

        elif op_type == 'unfreeze':
            account = op[1]
            if account in final_balances and account in frozen:
                frozen.remove(account)

    return final_balances, failed
